globalThis.TX_SEASON = {"title": "棠西村秘闻", "sourceSha256": "047b2b06ac78d5774b4356f929ea82af51ebab8a0ec569f6ebe2d9d04fcd7cd2", "start": "E00-S01", "chapters": [{"id": "E00", "title": "序章　七秒以后", "scenes": ["E00-S01", "E00-S02", "E00-S03", "E00-S04"]}, {"id": "E01", "title": "第一章　午夜便利店", "scenes": ["E01-S01", "E01-S02", "E01-S03", "E01-S04", "E01-S05"]}, {"id": "E02", "title": "第二章　卖不出去的阴宅", "scenes": ["E02-S01", "E02-S02", "E02-S03", "E02-S04", "E02-S05"]}, {"id": "E03", "title": "第三章　黑网吧·缺一人", "scenes": ["E03-S01", "E03-S02", "E03-S03", "E03-S04", "E03-S05"]}, {"id": "E04", "title": "第四章　肠粉摊的夜宵队", "scenes": ["E04-S01", "E04-S02", "E04-S03", "E04-S04"]}, {"id": "E05", "title": "第五章　楼顶晒衣绳", "scenes": ["E05-S01", "E05-S02", "E05-S03", "E05-S04", "E05-S05"]}, {"id": "E06", "title": "第六章　鱼缸房", "scenes": ["E06-S01", "E06-S02", "E06-S03", "E06-S04"]}, {"id": "E07", "title": "第七章　老生意街·三把钥匙", "scenes": ["E07-S01", "E07-S02", "E07-S03", "E07-S04", "E07-S05"]}, {"id": "E08", "title": "终章　今宵剧场", "scenes": ["E08-S01", "E08-S02", "E08-S03", "E08-S04", "E08-S05", "E08-S06", "E08-S07", "E08-S08"]}], "scenes": {
  "E00-S01": {"id": "E00-S01", "chapter": "E00", "title": "谁写的那行字", "next": "E00-S02", "time": "3月19日 傍晚", "place": "棠西村口的旧厂牌楼", "cue": "公交开远才听清巷里的雨声。摄影机从牌楼转回持麦的林雨；原帖只在手机内播放。", "beats": [
    {"id": "E00-S01.bus-arrival", "sourceLine": 104, "pickup": "bus-arrival", "type": "line", "speaker": "旁白", "text": "公交后门开在旧厂牌楼外。林雨先跳下去，回身接三脚架。你横过相机包，紧跟着下了车。车门在背后合上，她隔着玻璃跟司机挥了挥手。"},
    {"id": "E00-S01.bus-mic", "sourceLine": 106, "pickup": "bus-mic", "type": "line", "speaker": "林雨", "text": "阿岑，听得清吗？刚才车门夹着我这根线了。"},
    {"id": "E00-S01.bus-answer", "sourceLine": 108, "pickup": "bus-answer", "type": "line", "speaker": "阿岑", "text": "听得见。车上你叫我买两份炒粉，我这边都录得清清楚楚。"},
    {"id": "E00-S01.first-listen", "sourceLine": 110, "pickup": "first-listen", "type": "line", "speaker": "旁白", "text": "你把耳机戴回去。车一开走，巷子里滚轮碾过砖缝的声音就近了。厂区围墙里挤着一排出租楼。楼上有人端碗出来收衣服；楼下的小店刚把灯点亮，预备做夜班人的生意。林雨往里走了两步，回头等你的镜头。"},
    {"id": "E00-S01.channel", "sourceLine": 112, "pickup": "channel", "type": "line", "speaker": "林雨", "text": "晚上好，我是林雨。刚才接脚架的是我，拍我的是阿岑。我们俩平时做《夜访》，有人碰见解释不清的事，就发给我们。今天在广州棠西村。昨天我转了一段在这条巷子拍的视频。今早店家找来了，说因为我那行标题，有人堵到他妈店里去了。", "pages": ["晚上好，我是林雨。刚才接脚架的是我，拍我的是阿岑。我们俩平时做《夜访》，有人碰见解释不清的事，就发给我们。", "今天在广州棠西村。昨天我转了一段在这条巷子拍的视频。今早店家找来了，说因为我那行标题，有人堵到他妈店里去了。"]},
    {"id": "E00-S01.b01", "sourceLine": 114, "type": "line", "speaker": "林雨", "text": "阿岑，给大家看一眼这条路。镜头从牌楼往里走，到那盏灯牌就停。"},
    {"id": "E00-S01.b02", "sourceLine": 116, "type": "line", "speaker": "阿岑", "text": "停这儿你半张脸会被雨棚盖住。要绕过去，还是把右边那家店也带进去？"},
    {"id": "E00-S01.opening-water", "sourceLine": 118, "pickup": "opening-water", "type": "line", "speaker": "旁白", "text": "林雨把话筒从雨棚边递出去。一辆送水的三轮挤过她身后，箱子碰着台阶。"},
    {"id": "E00-S01.opening-frame", "sourceLine": 120, "pickup": "opening-frame", "type": "line", "speaker": "林雨", "text": "我往你这边站。人家刚找上门，咱别又把店名给拍进去。"},
    {"id": "E00-S01.opening-boundary", "sourceLine": 121, "pickup": "opening-boundary", "type": "line", "speaker": "阿岑", "text": "好，车过去了。你把昨天收到的那段给我。"},
    {"id": "E00-S01.opening-phone", "sourceLine": 123, "pickup": "opening-phone", "type": "line", "speaker": "旁白", "text": "林雨收回话筒，拿出手机。"},
    {"id": "E00-S01.b03", "sourceLine": 126, "type": "line", "speaker": "手机·夜访", "text": "昨夜投稿 · 7秒　「搭把手。」"},
    {"id": "E00-S01.b04", "sourceLine": 128, "type": "line", "speaker": "旁白", "text": "林雨把手机转过来。投稿下面还压着一条没读完的私信，雨棚底下有人搬水；镜头再往里一点，就会带到柜台。"},
    {"id": "E00-S01.b05", "sourceLine": 130, "type": "line", "speaker": "手机·店家的儿子", "text": "我是店里收银的。昨天你发完就有人摸过来。麻烦你跟他们讲一声，我妈还要做生意。"},
    {"id": "E00-S01.b06", "sourceLine": 132, "type": "line", "speaker": "阿岑", "text": "这是从柜台里往外拍的吧？都堵到人家收银台了。你后来转发时，写了什么？"},
    {"id": "E00-S01.b07", "sourceLine": 134, "type": "line", "speaker": "林雨", "text": "我记得只写了她喊人。你把我发的和她给的摆一起，我想再看一遍。"},
    {"id": "E00-S01.b08", "sourceLine": 136, "type": "interaction", "kind": "inspect", "prompt": "在手机里翻回昨夜的七秒。那行字是在哪儿加上的？", "options": [{"id": "E00-S01.b08.o1", "label": "打开投稿原件", "sourceLine": 138, "feedback": [{"id": "E00-S01.b08.o1.f1", "type": "line", "sourceLine": 140, "speaker": "声画", "text": "女孩喊「搭把手」，镜头偏向一扇落着的卷闸。右边是垂下来的雨棚。时间走到七秒，视频就停在那儿，没有字。"}]}, {"id": "E00-S01.b08.o2", "label": "打开《夜访》转发，再点“查看原片”", "sourceLine": 142, "feedback": [{"id": "E00-S01.b08.o2.f1", "type": "line", "sourceLine": 144, "speaker": "声画", "text": "同一扇卷闸、同一声雨；《夜访》的转发多了一行「整条巷，没人开门」。切回女孩发来的那份，那行字消失了。"}]}]},
    {"id": "E00-S01.b09", "sourceLine": 146, "type": "line", "speaker": "林雨", "text": "是我写的。画面一黑，我顺手就替她把后头也说完了。"},
    {"id": "E00-S01.b10", "sourceLine": 148, "type": "line", "speaker": "阿岑", "text": "那店里的人怎么办？底下还能点开地址。"},
    {"id": "E00-S01.b11", "sourceLine": 150, "type": "line", "speaker": "手机·水果头像", "text": "昨晚十点多我收工走这儿，铁牌响了三下。有把红伞在雨棚边叫我别靠沟。我就是站在牌楼底下拍的。你也站过去看看，能看见门吗？"},
    {"id": "E00-S01.b12", "sourceLine": 152, "type": "line", "speaker": "旁白", "text": "林雨先把转发藏了起来，再点开收银员那张照片，私信回他：「地址我撤了。我在附近，待会儿亲自跟阿姨说。」"},
    {"id": "E00-S01.b13", "sourceLine": 154, "type": "line", "speaker": "林雨", "text": "我先站到她站过的地方。阿岑，这回你替我看着边儿。镜头照不到哪儿，就告诉我照不到。"}
  ]},
  "E00-S02": {"id": "E00-S02", "chapter": "E00", "title": "棚边的半个字", "next": "E00-S03", "time": "3月19日 傍晚", "place": "牌楼下往三巷看的地方", "cue": "公交的尾灯消失在摄影师身后。保留刚才的灯箱、头顶棚边和脚下水沟。", "beats": [
    {"id": "E00-S02.b01", "sourceLine": 161, "type": "line", "speaker": "林雨", "text": "我刚才站这儿，能把整块招牌念下来。她拍的怎么就剩个「宵」？"},
    {"id": "E00-S02.b02", "sourceLine": 163, "type": "line", "speaker": "阿岑", "text": "你过来，站我这儿看。往店那头挪半步，那个字就出来一点。"},
    {"id": "E00-S02.b03", "sourceLine": 165, "type": "line", "speaker": "林雨", "text": "难怪她特意叫我们来。机子给我一下，我把最后一帧停住。"},
    {"id": "E00-S02.b04", "sourceLine": 167, "type": "line", "speaker": "旁白", "text": "林雨腾出一只手，往旁边让了让。一个裹蓝布头巾的女人抱着一盘塑料绳，从她让出的那点地方经过。阿岑看着取景器，脚还在原处。"},
    {"id": "E00-S02.b05", "sourceLine": 169, "type": "line", "speaker": "阿岑", "text": "你怎么又往后去了？小心，后头是沟。"},
    {"id": "E00-S02.b06", "sourceLine": 171, "type": "line", "speaker": "林雨", "text": "刚才有人要过。没事。你拿着机子，我报位置。"},
    {"id": "E00-S02.b07", "sourceLine": 173, "type": "interaction", "kind": "retry", "prompt": "从原片里半个「宵」字，找回女孩举手机的位置。", "options": [{"id": "E00-S02.b07.o1", "label": "站到便利店正门，认整块灯牌", "sourceLine": 175, "feedback": [{"id": "E00-S02.b07.o1.f1", "type": "line", "sourceLine": 177, "speaker": "动作", "text": "整个「今宵便利」都进了画面。林雨盯着原片里把字挡住的黑角，沿着雨棚往回走。"}], "retry": true}, {"id": "E00-S02.b07.o2", "label": "挪到缺角砖，让棚沿遮住半个“宵”", "sourceLine": 179, "feedback": [{"id": "E00-S02.b07.o2.f1", "type": "line", "sourceLine": 181, "speaker": "动作", "text": "鞋停在缺角砖上。灯箱只剩半个「宵」。卷闸还在，紧挨卷闸的那截墙却整个藏到了棚布后面。"}]}]},
    {"id": "E00-S02.b08", "sourceLine": 183, "type": "line", "speaker": "林雨", "text": "就在这儿。你站着别动，我走到那块棚布后面。看不见我了就喊。"},
    {"id": "E00-S02.b09", "sourceLine": 185, "type": "line", "speaker": "旁白", "text": "她沿墙走了三步。阿岑喊了声「没了」。林雨伸回半只手，指尖刚露出来。棚后有人正拆一箱水，就在这三步之外。"}
  ]},
  "E00-S03": {"id": "E00-S03", "chapter": "E00", "title": "雨棚后面那扇门", "next": "E00-S04", "time": "3月19日 入夜", "place": "今宵便利侧门", "cue": "先留空门，再从檐灯下看清阿琴。箱水卡在门槛，同一侧能看见卷闸和一条窄门缝。", "beats": [
    {"id": "E00-S03.b01", "sourceLine": 192, "type": "line", "speaker": "阿琴", "text": "要水啊？常温的在外面。劳驾先把脚让一下，这个门往外开的。"},
    {"id": "E00-S03.b02", "sourceLine": 194, "type": "line", "speaker": "旁白", "text": "林雨退下门槛。阿琴顶开窄门，箱子歪了一下，林雨伸手托住。两人一起把箱水搁到墙边。"},
    {"id": "E00-S03.b03", "sourceLine": 196, "type": "line", "speaker": "林雨", "text": "放这儿就稳了。老板，我叫林雨，《夜访》那行字是我写的。刚在牌楼下面试过，您这扇门我一点儿都看不到。"},
    {"id": "E00-S03.b04", "sourceLine": 198, "type": "line", "speaker": "阿琴", "text": "原来是你。我儿子说有人回他了。那你朋友肩膀上那个红点，是还在拍我吗？"},
    {"id": "E00-S03.b05", "sourceLine": 200, "type": "interaction", "kind": "choice", "prompt": "阿琴等着看阿岑手里的相机。怎么回应她？", "options": [{"id": "E00-S03.b05.o1", "label": "让她亲眼看阿岑停机", "sourceLine": 202, "feedback": [{"id": "E00-S03.b05.o1.f1", "type": "line", "sourceLine": 204, "speaker": "阿岑", "text": "您看这个点。我按一下……灭了。机子我搁这儿。"}, {"id": "E00-S03.b05.o1.f2", "type": "line", "sourceLine": 205, "speaker": "阿琴", "text": "搁干的那箱。下面那箱淋过，一压就塌。"}]}, {"id": "E00-S03.b05.o2", "label": "把解锁的手机交给她，阿岑盖镜头", "sourceLine": 207, "feedback": [{"id": "E00-S03.b05.o2.f1", "type": "line", "sourceLine": 209, "speaker": "阿琴", "text": "他盖住了？行。你给我找找，我在我儿子的手机上只看见有字的那份。"}, {"id": "E00-S03.b05.o2.f2", "type": "line", "sourceLine": 210, "speaker": "林雨", "text": "您拿着。我帮您往回拖。到七秒，它自己就停了。"}]}]},
    {"id": "E00-S03.b06", "sourceLine": 212, "type": "line", "speaker": "旁白", "text": "等阿岑的手离开相机，阿琴把卷闸又往下拉了一截。闸没碰地，她另一只手已经推开了旁边的窄门。「两扇」，她说。"},
    {"id": "E00-S03.b07", "sourceLine": 214, "type": "line", "speaker": "阿琴", "text": "我们晚了收这扇大的，旁边留着让人过。昨晚谁从这儿进，你得问那天守门的。我当时在后头点货。"},
    {"id": "E00-S03.lens-off", "sourceLine": 216, "pickup": "lens-off", "when": "E00-S03.b05.o1", "type": "line", "speaker": "阿岑", "text": "那一下推门刚好没录。要不我画给你，回去你照着讲？"},
    {"id": "E00-S03.phone-back", "sourceLine": 217, "pickup": "phone-back", "when": "E00-S03.b05.o2", "type": "line", "speaker": "阿琴", "text": "我拖到头了。门在我现在站的这边，昨晚拍的人站得远，够不着这里。"},
    {"id": "E00-S03.b08", "sourceLine": 219, "type": "line", "speaker": "林雨", "text": "我能把门拍给昨天看过的人吗？从棚边拍一张，再站过来拍这根门轴。您站我身后看取景。"},
    {"id": "E00-S03.b09", "sourceLine": 221, "type": "line", "speaker": "阿琴", "text": "我来推，你只拍我这只手。别绕进店，有客人结账。"},
    {"id": "E00-S03.b10", "sourceLine": 223, "type": "line", "speaker": "林雨", "text": "好。阿岑，你拍完把两张摆一块儿，先给老板看。"},
    {"id": "E00-S03.b11", "sourceLine": 225, "type": "line", "speaker": "阿琴", "text": "成。我叫阿琴。你俩挪到檐下拍去，站这儿又该淋着了。"},
    {"id": "E00-S03.b12", "sourceLine": 227, "type": "set", "text": "阿琴允许的门铰链影像", "record": "hinge", "scope": "public", "holder": "阿琴／夜访", "detail": "仅可示范当天的门、手与机位遮挡。"}
  ]},
  "E00-S04": {"id": "E00-S04", "chapter": "E00", "title": "等一班车的工夫", "next": "E01-S01", "time": "3月19日 夜", "place": "牌楼外的公交站", "cue": "店灯留在来路。琴姐已看过两张定格，等上车的两个人在手机上处理旧帖。", "beats": [
    {"id": "E00-S04.b01", "sourceLine": 234, "type": "line", "speaker": "旁白", "text": "林雨把两张图摆在手机上。左边是棚下缺角砖看出去的卷闸，右边是琴姐推窄门的手。「同一家店，走三步。」她读完自己刚打的字，删掉了最后那句「幸好有人开了门」。"},
    {"id": "E00-S04.proof", "sourceLine": 236, "pickup": "proof", "type": "line", "speaker": "阿岑", "text": "怎么把这句也删了？"},
    {"id": "E00-S04.correct", "sourceLine": 237, "pickup": "correct", "type": "line", "speaker": "林雨", "text": "咱俩见的是今天这只手。昨天那只手是谁的，我还不知道。现在能告诉人家的就这两张图。"},
    {"id": "E00-S04.b02", "sourceLine": 239, "type": "interaction", "kind": "choice", "prompt": "怎样让看过旧标题的人找到这两张对照？", "options": [{"id": "E00-S04.b02.o1", "label": "恢复带遮挡的更正入口，置顶两帧对照；隐藏原定位", "sourceLine": 241, "feedback": [{"id": "E00-S04.b02.o1.f1", "type": "line", "sourceLine": 243, "speaker": "手机·夜访", "text": "打开旧链接，第一屏已经换成两张图。「站在投稿的位置，看不见侧门。」店名和门牌隐去了。"}]}, {"id": "E00-S04.b02.o2", "label": "保持旧帖隐藏，以频道主页置顶更正", "sourceLine": 245, "feedback": [{"id": "E00-S04.b02.o2.f1", "type": "line", "sourceLine": 247, "speaker": "手机·夜访", "text": "旧链接仍显示不可见。林雨把主页的两张图发回原来那几个转发里，给店里收银的儿子也留了一份。"}]}]},
    {"id": "E00-S04.b03", "sourceLine": 249, "type": "line", "speaker": "阿岑", "text": "我在棚下喊你那会儿，你说有人经过。你记得那人往哪头走的吗？"},
    {"id": "E00-S04.b04", "sourceLine": 251, "type": "line", "speaker": "林雨", "text": "你真没看见？蓝头巾，怀里这么大一卷绳。往里面去的。"},
    {"id": "E00-S04.b05", "sourceLine": 253, "type": "line", "speaker": "阿岑", "text": "我听见有人蹭了下棚布。我还怪你碰着话筒了。"},
    {"id": "E00-S04.b06", "sourceLine": 255, "type": "line", "speaker": "林雨", "text": "明天白天再认吧。这个先别往帖子里放。"},
    {"id": "E00-S04.b07", "sourceLine": 257, "type": "line", "speaker": "手机·水果头像", "text": "两张图我看到了。明晚九点，我在三巷铁牌下面等你。休息只有十分钟，别开着机器来。"},
    {"id": "E00-S04.b08", "sourceLine": 259, "type": "line", "speaker": "林雨", "text": "原来她一直在看。回她一句「好」。我自己回。"},
    {"id": "E00-S04.b09", "sourceLine": 261, "type": "line", "speaker": "旁白", "text": "车来了。林雨扶着栏杆给明天上了闹钟：八点半，去见发七秒的人。地址那一栏，她这回一个字也没填。"}
  ]},
  "E01-S01": {"id": "E01-S01", "chapter": "E01", "title": "铁牌下面等人", "next": "E01-S02", "time": "3月20日 21:00", "place": "三巷铁牌下", "cue": "铁牌还没有响。先让玩家认出昨晚路过的雨棚，才有人从檐下叫林雨。", "beats": [
    {"id": "E01-S01.b01", "sourceLine": 272, "type": "line", "speaker": "旁白", "text": "九点整，一个挂着夜班工牌的姑娘站到了铁牌下面。她看了一眼林雨肩后的阿岑，又看了一眼那台垂在他胸前的相机。林雨把它的关机拨杆转给她看。"},
    {"id": "E01-S01.b02", "sourceLine": 274, "type": "line", "speaker": "小茵", "text": "给你发私信的那个，头像是一只橙子，就是我。叫我小茵就好，名字别上节目。我就歇十分钟。你们昨天去店里，琴姐肯让拍啊？"},
    {"id": "E01-S01.ten-minutes", "sourceLine": 276, "pickup": "ten-minutes", "type": "line", "speaker": "林雨", "text": "名字我记住了。你看，拨杆在这儿，机器关着。你要是不放心，拿盖子扣上也行。"},
    {"id": "E01-S01.b03", "sourceLine": 278, "when": "E00-S03.b05.o1", "type": "line", "speaker": "林雨", "text": "起先不肯。阿岑关了机，她才肯跟我说话。后来是她自己推的门，让我们只拍她那只手。"},
    {"id": "E01-S01.b04", "sourceLine": 279, "when": "E00-S03.b05.o2", "type": "line", "speaker": "林雨", "text": "我们先盖住镜头，把原片给她看。门轴那张是她自己推的，她站在我后头看我拍。"},
    {"id": "E01-S01.b05", "sourceLine": 281, "type": "line", "speaker": "阿岑", "text": "你手机红了一格。接我这个吧，线也在上头。你自己拿着。"},
    {"id": "E01-S01.b06", "sourceLine": 283, "type": "line", "speaker": "小茵", "text": "谢了。那晚我就在对街给琴姐拍这个。拴牌的绳子松了，我想让她听听，是牌自己晃，还是有人敲。后来有个女的喊我搭把手。"},
    {"id": "E01-S01.permission.1", "sourceLine": 285, "pickup": "permission.1", "type": "line", "speaker": "小茵", "text": "我把前面七秒私信给你，是因为你说你听得出那些动静。你怎么把它放出去了？"},
    {"id": "E01-S01.permission.2", "sourceLine": 286, "pickup": "permission.2", "type": "line", "speaker": "林雨", "text": "我看见「投稿」两个字，就当你答应了。那是我想当然。你发给我时问了什么，我都没回。"},
    {"id": "E01-S01.b07", "sourceLine": 288, "type": "line", "speaker": "林雨", "text": "我现在回你。三下，我听见了。七秒以后呢？那女的喊你，你过去了吗？"},
    {"id": "E01-S01.b08", "sourceLine": 290, "type": "line", "speaker": "小茵", "text": "过去了。手机往兜里一塞，人还在跑，它还在录。我推开侧门，叫她进来。你们那个标题没给这几步留地方。"},
    {"id": "E01-S01.b09", "sourceLine": 292, "type": "line", "speaker": "阿岑", "text": "我昨晚还说是你把手机关了。敢情后头一直录着，都在你兜里。"},
    {"id": "E01-S01.b10", "sourceLine": 294, "type": "line", "speaker": "小茵", "text": "我要回去接线了。十点一刻再歇一回，我给琴姐送对账单。你们到店里等我吧，我把后头找出来给你听。"},
    {"id": "E01-S01.b11", "sourceLine": 296, "type": "line", "speaker": "旁白", "text": "她拎起放工牌的袋子，充电宝连着手机晃在外头。林雨替她把两样一块儿塞进侧袋。"},
    {"id": "E01-S01.b12", "sourceLine": 298, "type": "line", "speaker": "小茵", "text": "就先借我这一阵子啊。你俩可别等烦了把店都拍完了。"}
  ]},
  "E01-S02": {"id": "E01-S02", "chapter": "E01", "title": "雨棚尽头的脚步", "next": "E01-S03", "time": "3月20日 22:18", "place": "今宵便利门口", "cue": "冷柜在檐下。过沟的那块长玻璃能照出身后；阿岑留在有灯的这侧。", "beats": [
    {"id": "E01-S02.b01", "sourceLine": 305, "type": "line", "speaker": "旁白", "text": "十点十八，手机亮了一下。「还有个电话没挂，晚几分钟。最后这两声先给你们听。」林雨戴上一边耳机。重的一声过后，还有个轻响。就在这时，阿琴放下冰柜盖，身边也响了这么两下。"},
    {"id": "E01-S02.b02", "sourceLine": 307, "type": "interaction", "kind": "inspect", "prompt": "趁那一下还记得，试试柜子上哪件东西会晚响。", "options": [{"id": "E01-S02.b02.o1", "label": "点柜盖上的活动提手", "sourceLine": 309, "feedback": [{"id": "E01-S02.b02.o1.f1", "type": "line", "sourceLine": 311, "speaker": "动作", "text": "阿岑按稳柜盖，只让提手落下。薄薄的一声。林雨退回去听小茵发的那段，把耳机递给他。两声对得上。"}]}, {"id": "E01-S02.b02.o2", "label": "点柜沿，再让阿琴把提手压住", "sourceLine": 313, "feedback": [{"id": "E01-S02.b02.o2.f1", "type": "line", "sourceLine": 315, "speaker": "动作", "text": "阿琴握紧提手，放下柜盖。这回只有沉的那声。松开手，小响才跟上来。阿岑朝耳机点点头。"}]}]},
    {"id": "E01-S02.reason", "sourceLine": 317, "pickup": "reason", "type": "line", "speaker": "林雨", "text": "听着像这个提手。先记着，等她回来自己认。你在店门口等，我去铁牌那儿接她。雨这么大，她还拿着单子。"},
    {"id": "E01-S02.b03", "sourceLine": 318, "type": "line", "speaker": "旁白", "text": "林雨走过水沟，脚下慢下来。雨棚尽头那块玻璃上，除了她，还有个穿夹克的男人。她停下来系本来就系紧的鞋带。那个人也停了。"},
    {"id": "E01-S02.b04", "sourceLine": 320, "type": "line", "speaker": "林雨", "text": "阿岑，你在侧门那儿等我。先别转头。有人跟到沟边了。"},
    {"id": "E01-S02.b05", "sourceLine": 322, "type": "line", "speaker": "阿岑", "text": "我看得见你。你往灯这边走，我站门口。"},
    {"id": "E01-S02.b06", "sourceLine": 324, "type": "line", "speaker": "旁白", "text": "她直起身。对面的阿岑没动，她身后却响了一步。雨忽然没打在她头上了。一把暗红的伞从旁边遮过来，伞下的女人把自己的半边肩膀留在雨里。", "pages": ["她直起身。对面的阿岑没动，她身后却响了一步。", "雨忽然没打在她头上了。一把暗红的伞从旁边遮过来，伞下的女人把自己的半边肩膀留在雨里。"]}
  ]},
  "E01-S03": {"id": "E01-S03", "chapter": "E01", "title": "还有人等你吃粉", "next": "E01-S04", "time": "3月20日 22:23", "place": "水沟到便利店侧门", "cue": "保持水沟、铁牌、窄门三处位置。三响有回应，林雨先过门槛，跟踪者才离开。", "beats": [
    {"id": "E01-S03.b01", "sourceLine": 331, "type": "line", "speaker": "林雨", "text": "阿婆，您也往灯底下去吗？我跟您走一段。"},
    {"id": "E01-S03.b02", "sourceLine": 333, "type": "line", "speaker": "旁白", "text": "阿婆没催她。握伞的手从伞布下面伸出来，腕上绑着一小截蓝布。伞柄在铁牌上敲了三下。对街的拖把磕到墙，紧接着，窄门上头的灯亮了。", "pages": ["阿婆没催她。握伞的手从伞布下面伸出来，腕上绑着一小截蓝布。", "伞柄在铁牌上敲了三下。", "对街的拖把磕到墙，紧接着，窄门上头的灯亮了。"]},
    {"id": "E01-S03.b03", "sourceLine": 335, "type": "interaction", "kind": "choice", "prompt": "琴姐从门里望出来。让她看清水沟这边是谁。", "options": [{"id": "E01-S03.b03.o1", "label": "喊阿琴帮忙", "sourceLine": 337, "feedback": [{"id": "E01-S03.b03.o1.f1", "type": "line", "sourceLine": 339, "speaker": "林雨", "text": "琴姐，是我！门留一下！"}, {"id": "E01-S03.b03.o1.f2", "type": "line", "sourceLine": 340, "speaker": "阿琴", "text": "听见了！水漫到哪儿你可看不见。踩那块平砖，慢慢儿过。"}]}, {"id": "E01-S03.b03.o2", "label": "亮起手机照窄门的门槛", "sourceLine": 342, "feedback": [{"id": "E01-S03.b03.o2.f1", "type": "line", "sourceLine": 344, "speaker": "动作", "text": "手机灯扫过积水，照到阿琴围裙的下摆。阿琴把拖把靠在墙上，向林雨招手，又指了指露出水面的砖。"}]}]},
    {"id": "E01-S03.b04", "sourceLine": 346, "type": "line", "speaker": "阿琴", "text": "靓仔，你跟在后面这么久了，也要进来买东西啊？"},
    {"id": "E01-S03.b05", "sourceLine": 348, "type": "line", "speaker": "旁白", "text": "男人没应声。斜对面，粉叔用脚把横在过道上的矮凳勾回摊底，端起一只碟子举过肩，隔着雨声朝水沟这边望。"},
    {"id": "E01-S03.b06", "sourceLine": 350, "type": "line", "speaker": "粉叔", "text": "妹仔！不是叫你过来吃的？等你一人呢。"},
    {"id": "E01-S03.threshold.1", "sourceLine": 352, "pickup": "threshold.1", "type": "line", "speaker": "旁白", "text": "阿琴接住门把手，让窄门再开大一点。她先把拖把横到门内，腾出门槛中间那一条干处。", "pages": ["阿琴接住门把手，让窄门再开大一点。", "她先把拖把横到门内，腾出门槛中间那一条干处。"]},
    {"id": "E01-S03.b07", "sourceLine": 354, "type": "line", "speaker": "旁白", "text": "林雨看见了，是只空碟，却没再往沟那头走。她先踩上那块平砖。阿岑往门框边一靠，把门中间让给她。鞋后跟落进屋里，她才回头。男人还站在外边。见几个人都朝他看，他扭头走了。", "pages": ["林雨看见了，是只空碟，却没再往沟那头走。", "她先踩上那块平砖。", "阿岑往门框边一靠，把门中间让给她。鞋后跟落进屋里，她才回头。", "男人还站在外边。见几个人都朝他看，他扭头走了。"]},
    {"id": "E01-S03.b08", "sourceLine": 356, "type": "line", "speaker": "阿琴", "text": "先进来。粉叔那碟等得起。"},
    {"id": "E01-S03.b09", "sourceLine": 358, "type": "line", "speaker": "阿琴", "text": "我叫小茵回来陪你过去。你先在这儿站一会儿，别又踩回水里。"},
    {"id": "E01-S03.b10", "sourceLine": 360, "type": "line", "speaker": "旁白", "text": "他在斜对面拧开了炉火。林雨从琴姐手里接过一条干毛巾，没再往外递，只把它攥在掌心。檐外还在滴水，刚刚的红伞已经看不见了。", "pages": ["他在斜对面拧开了炉火。", "林雨从琴姐手里接过一条干毛巾，没再往外递，只把它攥在掌心。檐外还在滴水，刚刚的红伞已经看不见了。"]}
  ]},
  "E01-S04": {"id": "E01-S04", "chapter": "E01", "title": "没录进去的那个人", "next": "E01-S05", "time": "3月20日 22:30", "place": "窄门斜对面的粉摊", "cue": "始终能从棚下看见刚走过的窄门。让小茵自己拿着手机，裁到实际的门响。", "beats": [
    {"id": "E01-S04.b01", "sourceLine": 367, "type": "line", "speaker": "旁白", "text": "小茵拎着对账单从店里出来，工牌还晃在胸前。她看见林雨手里攥着毛巾，先把自己的手机塞回侧袋。"},
    {"id": "E01-S04.b02", "sourceLine": 369, "type": "line", "speaker": "小茵", "text": "我歇够了，陪你过沟。你只踩琴姐刚指的那块砖；粉叔那边我叫他别把碟端凉。"},
    {"id": "E01-S04.b03", "sourceLine": 371, "type": "line", "speaker": "旁白", "text": "阿琴留在窄门里看着。小茵先踩上平砖，回头等林雨跟上。两人过到粉摊棚下，粉叔才把热碟端到桌边。", "pages": ["阿琴留在窄门里看着。小茵先踩上平砖，回头等林雨跟上。", "两人过到粉摊棚下，粉叔才把热碟端到桌边。"]},
    {"id": "E01-S04.b04", "sourceLine": 373, "type": "line", "speaker": "林雨", "text": "粉叔，你举个空碟，还真把我叫进来了。"},
    {"id": "E01-S04.b05", "sourceLine": 375, "type": "line", "speaker": "粉叔", "text": "谁说空的？你坐稳，给我两分钟。"},
    {"id": "E01-S04.b06", "sourceLine": 377, "type": "line", "speaker": "旁白", "text": "林雨用鞋尖把矮凳往外勾了勾，给小茵腾了个座。小茵解下工牌，从侧袋掏出阿岑的充电宝，连线一块儿放回他手里。"},
    {"id": "E01-S04.towel-grip", "sourceLine": 379, "pickup": "towel-grip", "type": "line", "speaker": "旁白", "text": "林雨把手搁上碗沿，布也跟着过去了。她这才发现那条干毛巾一直攥在手心。小茵替她把水倒好，等着她自己松手。"},
    {"id": "E01-S04.b07", "sourceLine": 381, "type": "line", "speaker": "小茵", "text": "刚才那一下你腿都在抖。还想听吗？我以前也这么跑过一回，你坐着听就好。"},
    {"id": "E01-S04.believe.1", "sourceLine": 383, "pickup": "believe.1", "type": "line", "speaker": "小茵", "text": "你刚跟琴姐说，外头有个打红伞的阿婆。我没看见。你也没问我要证据才肯跟她走吧？"},
    {"id": "E01-S04.believe.2", "sourceLine": 384, "pickup": "believe.2", "type": "line", "speaker": "林雨", "text": "没有。你说你开的门，我也信。你不愿意放就算了，昨天那句话，我照样得收回来。"},
    {"id": "E01-S04.decision", "sourceLine": 385, "pickup": "decision", "type": "line", "speaker": "小茵", "text": "我愿意让那几个堵柜台的人听见门开。再往后，我妈喊我小名，那句留给我自己。"},
    {"id": "E01-S04.thumb", "sourceLine": 387, "pickup": "thumb", "type": "line", "speaker": "旁白", "text": "她点开原件。袖子擦话筒，柜盖回落，然后一声长长的门轴响。她的拇指压在进度条上。"},
    {"id": "E01-S04.b08", "sourceLine": 389, "type": "line", "speaker": "阿岑", "text": "再往前一点就够。你按停，我们等你发。"},
    {"id": "E01-S04.b09", "sourceLine": 391, "type": "line", "speaker": "林雨", "text": "我把开门声接在昨天那两张图后面。你看看这行字行不行：「那晚有人开过门。标题写错了。林雨。」"},
    {"id": "E01-S04.b10", "sourceLine": 393, "when": "E00-S04.b02.o1", "type": "line", "speaker": "手机·评论通知", "text": "原链接里有人问「她后来进去了吗」。小茵看完点了点头，林雨把更正贴回那条评论下面。"},
    {"id": "E01-S04.b11", "sourceLine": 394, "when": "E00-S04.b02.o2", "type": "line", "speaker": "手机·私信", "text": "有人私信追问旧片去了哪里。小茵看完点了点头，林雨把主页更正发给他，旧片依旧藏着。"},
    {"id": "E01-S04.b12", "sourceLine": 396, "type": "line", "speaker": "旁白", "text": "收起手机，林雨拿毛巾擦了擦刚才腾出来的位置。湿玻璃纸下浮出四个金漆字：张记糖水。那个「张」字的边儿都快磨没了。"},
    {"id": "E01-S04.b13", "sourceLine": 398, "type": "line", "speaker": "林雨", "text": "粉叔，我刚从伞下看出去，她要去的像是这张桌。以前这里卖糖水？"},
    {"id": "E01-S04.b14", "sourceLine": 400, "type": "line", "speaker": "粉叔", "text": "嗯。张婆婆的。人走了六年，桌子还结实，我就拿来用了。你说那把伞，她那时候常搁在桌脚。"},
    {"id": "E01-S04.across-gutter", "sourceLine": 402, "pickup": "across-gutter", "type": "line", "speaker": "旁白", "text": "店门口的阿琴正把门楔踢紧。听见张婆婆的名字，她隔着水沟接了一句。"},
    {"id": "E01-S04.b15", "sourceLine": 404, "type": "line", "speaker": "阿琴", "text": "她等晚班收工的女孩子一起走。雨大了，伞就留给人家。第二天来还，总能混到碗糖水。"},
    {"id": "E01-S04.b16", "sourceLine": 406, "type": "line", "speaker": "旁白", "text": "林雨把毛巾叠好，放在写着「张」字的那一角。过了一会儿，她低下头，吃起面前那份已经不烫嘴的粉。"},
    {"id": "E01-S04.b17", "sourceLine": 408, "type": "set", "text": "开门声的限段许可", "record": "door-sound", "scope": "public", "holder": "小茵", "detail": "她亲自裁到门轴响。姓名、定位和母亲叫乳名的声音只留在本人手机。"}
  ]},
  "E01-S05": {"id": "E01-S05", "chapter": "E01", "title": "四个叉烧包", "next": "E02-S01", "time": "3月20日 23:05 至3月27日", "place": "今宵便利与三巷十二号", "cue": "从粉摊回店还毛巾；纸袋始终空着。隔日找人、数次返村和正式入住需给日期与方位。", "beats": [
    {"id": "E01-S05.b01", "sourceLine": 415, "type": "line", "speaker": "旁白", "text": "粉摊开始收碟。林雨拎起碟脚压住的那条毛巾，送回斜对面的店里。蒸柜边一位老人正仰头挑包子。他指一个，数一个，到第四个，把手伸向架子上的牛皮纸袋。"},
    {"id": "E01-S05.b02", "sourceLine": 417, "type": "line", "speaker": "老人", "text": "大的放上面。底下那两个要是给压瘪了，他们回去又要拣。"},
    {"id": "E01-S05.b03", "sourceLine": 419, "type": "line", "speaker": "旁白", "text": "纸袋落下来。阿岑以为是风吹的，伸手接住。林雨问老人要不要再拿个袋，阿岑跟着望过去，柜前空空的。收银机响了，跟买水的小票连在一起的还有一截湿纸，背面印着倒过来的「郑家楼」。", "pages": ["纸袋落下来。阿岑以为是风吹的，伸手接住。林雨问老人要不要再拿个袋，阿岑跟着望过去，柜前空空的。", "收银机响了，跟买水的小票连在一起的还有一截湿纸，背面印着倒过来的「郑家楼」。"]},
    {"id": "E01-S05.b04", "sourceLine": 421, "type": "line", "speaker": "阿琴", "text": "四个都拣圆的？那是福顺伯，郑家楼的。以前他早班下工，天天给四个孩子买。你先把袋子给我，纸也别丢。我明早带你去问他大儿子。"},
    {"id": "E01-S05.b05", "sourceLine": 423, "type": "line", "speaker": "旁白", "text": "天亮后阿琴领他们走到巷尾，找郑家长子。铁闸落着。阿琴给铺主留了电话。接连几天，林雨有时过来等回话，有时只是过来吃饭。"},
    {"id": "E01-S05.supper.1", "sourceLine": 425, "pickup": "supper.1", "type": "line", "speaker": "旁白", "text": "第三回，小茵没带旧手机，林雨也没带机子。两个人吃完才发现。「明天还来吗？」小茵问。林雨把空碟往摊里递：「有清早的活就不来。晚了给你留个位子。」"},
    {"id": "E01-S05.b06", "sourceLine": 427, "type": "line", "speaker": "阿岑", "text": "算上明早那趟，车钱快够你在这儿住一个礼拜了。楼上招租那张纸，你是不是已经抄过电话了？"},
    {"id": "E01-S05.b07", "sourceLine": 429, "type": "line", "speaker": "林雨", "text": "问过了，一间够我放剪片的电脑。你还睡你家。真有早班，你把电池留我这儿充，比咱俩半夜坐车强。"},
    {"id": "E01-S05.b08", "sourceLine": 431, "type": "line", "speaker": "老许", "text": "电话里说姓林的，是你啊？来，看看水表。三楼临街这间九百，押一个月。你伙伴就帮你搬东西？那租约我只写你。"},
    {"id": "E01-S05.b09", "sourceLine": 433, "type": "line", "speaker": "旁白", "text": "三月二十七，林雨在三〇二签了一个月。老许把钥匙放她手心里，阿岑把电脑放到靠墙的桌上。插线板掉进床缝，够不着了。"},
    {"id": "E01-S05.b10", "sourceLine": 435, "type": "line", "speaker": "林雨", "text": "许叔，搭把手？我抬床头，你帮我往外挪一寸就够。"},
    {"id": "E01-S05.b11", "sourceLine": 437, "type": "line", "speaker": "老许", "text": "靠窗那头给我，底下垫的砖会跑。好，你伸手。"},
    {"id": "E01-S05.b12", "sourceLine": 439, "type": "line", "speaker": "旁白", "text": "床让开了。林雨捡到插线板，也看见矮柜上那台旧电视。插头还盘着，黑玻璃里却有张别处的饭桌。桌边坐着蒸柜前那位老人，面前的四个包子还在袋里。阿岑顺着她的手看过去，只看见他俩并排蹲在地上的倒影。", "pages": ["床让开了。林雨捡到插线板，也看见矮柜上那台旧电视。插头还盘着，黑玻璃里却有张别处的饭桌。桌边坐着蒸柜前那位老人，面前的四个包子还在袋里。", "阿岑顺着她的手看过去，只看见他俩并排蹲在地上的倒影。"]},
    {"id": "E01-S05.b13", "sourceLine": 441, "type": "set", "text": "302短租与钥匙", "record": "lease", "scope": "private", "holder": "林雨／老许", "detail": "租约与房钥匙供居住和交还时核对。"}
  ]},
  "E02-S01": {"id": "E02-S01", "chapter": "E02", "title": "四个包", "next": "E02-S02", "time": "4月4日 下午", "place": "郑家楼前", "cue": "雨收了；铁门上贴着长子的售房电话", "beats": [
    {"id": "E02-S01.b01", "sourceLine": 452, "type": "line", "speaker": "旁白", "text": "林雨的手机在雨棚下震了一下。郑国强的回电只有一句：下午他会来撕楼口广告；要来，就那会儿来。阿琴照这句话把地址写在便利店小票背面，带林雨和阿岑走到巷尾，自己停在雨棚外。"},
    {"id": "E02-S01.b02", "sourceLine": 454, "type": "line", "speaker": "阿琴", "text": "福顺伯失踪以后，是国强贴的电话。他肯不肯开门，得他自己说。这四个包是粉叔看我又淋雨，塞给咱们垫肚子的；别拿它去换人家的话。"},
    {"id": "E02-S01.b03", "sourceLine": 456, "type": "line", "speaker": "旁白", "text": "林雨接过纸袋。袋里四个叉烧包，最小的一个面皮上掐着花。她把它放回最底下，没再问阿琴。"},
    {"id": "E02-S01.b04", "sourceLine": 458, "type": "line", "speaker": "旁白", "text": "郑国强正蹲在门边铲掉一张褪色的小广告，听见脚步才抬头。他袖口沾着浆糊，钥匙攥在掌心里，压出一圈红印。"},
    {"id": "E02-S01.b05", "sourceLine": 460, "type": "line", "speaker": "郑国强", "text": "看楼还是看房？看房留电话。看我爸，派出所那边有登记。"},
    {"id": "E02-S01.b06", "sourceLine": 462, "type": "line", "speaker": "林雨", "text": "都不是。阿琴带我们到楼口，说您自己决定见不见。我们想问当年那张寻人启事还在不在；不想谈，我们现在就走。"},
    {"id": "E02-S01.b07", "sourceLine": 464, "type": "line", "speaker": "林雨", "text": "派出所的登记我不问，也不进地下杂物房。那张启事是您写的，我只拍日期和“寻人”两个字，电话不进镜头。"},
    {"id": "E02-S01.b08", "sourceLine": 466, "type": "line", "speaker": "郑国强", "text": "那上面是我写的，不是我爸留的。拍完给我看一眼。"},
    {"id": "E02-S01.b09", "sourceLine": 468, "type": "line", "speaker": "旁白", "text": "林雨把取景框压到纸的下半截。郑国强看完屏幕，才把卷闸钥匙插回口袋。阿岑抬头看见楼梯灯还亮着，顺手把补光灯关了。"},
    {"id": "E02-S01.b10", "sourceLine": 470, "type": "line", "speaker": "阿岑", "text": "这灯一直开着？"},
    {"id": "E02-S01.b11", "sourceLine": 472, "type": "line", "speaker": "郑国强", "text": "我每回来一趟就开一次，省得有人摔。别顺着这个猜我爸在楼上。"},
    {"id": "E02-S01.b12", "sourceLine": 474, "type": "line", "speaker": "郑国强", "text": "楼挂牌两年，来看的人听见“老人失踪”就走。你们要上去，只看楼梯和启事。地下杂物房漏水，谁也别下。十分钟后我得回隔壁看铺。"},
    {"id": "E02-S01.b13", "sourceLine": 476, "type": "line", "speaker": "阿岑", "text": "十分钟到了，我们自己出来；您不用在楼上等。"},
    {"id": "E02-S01.b14", "sourceLine": 478, "type": "line", "speaker": "旁白", "text": "郑国强把铁门推开一条只够一人侧身的缝。阿琴没有跟进去，只朝林雨抬了抬下巴。"},
    {"id": "E02-S01.b15", "sourceLine": 480, "type": "line", "speaker": "阿琴", "text": "我在粉叔那边。出来了把袋子给我，凉了我自己吃。"},
    {"id": "E02-S01.b16", "sourceLine": 482, "type": "line", "speaker": "旁白", "text": "楼道里没有人。林雨走到第一段台阶，身后纸袋却忽然透出热气。"}
  ]},
  "E02-S02": {"id": "E02-S02", "chapter": "E02", "title": "一楼上面还是一楼", "next": "E02-S03", "time": "4月4日 黄昏", "place": "郑家楼梯与饭厅", "cue": "现实墙痕固定；林雨层门牌重叠；无时限回退", "beats": [
    {"id": "E02-S02.b01", "sourceLine": 489, "type": "line", "speaker": "旁白", "text": "阿岑在扶手上系了一截黑色绕线带，留在郑国强看得见的第一层。他站回门边，手机计时停在八分多钟。"},
    {"id": "E02-S02.b02", "sourceLine": 491, "type": "line", "speaker": "阿岑", "text": "灯、启事、绕线带。我在这儿喊，你听见就回一声。别为了多看一眼，把人家的十分钟耗没了。"},
    {"id": "E02-S02.b03", "sourceLine": 493, "type": "line", "speaker": "旁白", "text": "林雨点头，往上走。门牌上又是“一楼”。她回头，绕线带却像在更高的一层。"},
    {"id": "E02-S02.b04", "sourceLine": 495, "type": "interaction", "kind": "retry", "prompt": "找能区分两趟楼梯的东西。", "options": [{"id": "E02-S02.b04.o1", "label": "只数门上亮着的“一楼”", "sourceLine": 497, "feedback": [{"id": "E02-S02.b04.o1.f1", "type": "line", "sourceLine": 499, "speaker": "动作", "text": "她数到第三块同样的搪瓷牌。阿岑在楼下喊了一声，声音却从头顶掉下来。"}], "retry": true}, {"id": "E02-S02.b04.o2", "label": "沿扶手找阿岑系的黑色绕线带", "sourceLine": 501, "feedback": [{"id": "E02-S02.b04.o2.f1", "type": "line", "sourceLine": 503, "speaker": "动作", "text": "第一次绕带在左，第二次右手摸到的是光木头。林雨退回绕带所在的一层；墙上多出一扇虚掩的饭厅门。"}]}]},
    {"id": "E02-S02.b05", "sourceLine": 505, "type": "line", "speaker": "旁白", "text": "她没有伸手推。门里先传来瓷勺碰碗，接着是老人慢慢数筷子的声音。一只手把几双短筷平码在桌边。林雨扶着门探进半个身子，看见数筷子的老人还给人留了座。", "pages": ["她没有伸手推。门里先传来瓷勺碰碗，接着是老人慢慢数筷子的声音。", "一只手把几双短筷平码在桌边。林雨扶着门探进半个身子，看见数筷子的老人还给人留了座。"]},
    {"id": "E02-S02.b06", "sourceLine": 507, "type": "line", "speaker": "福顺伯", "text": "一、二、三……刚才明明洗了四双。"},
    {"id": "E02-S02.b07", "sourceLine": 509, "type": "line", "speaker": "旁白", "text": "饭厅的长桌比现实楼梯宽得多。墙上奖状旁有四个钉眼，桌上只摆着三双短筷子。福顺伯正用手背试汤碗的温度，把最矮的一张凳子推向空位。"},
    {"id": "E02-S02.b08", "sourceLine": 511, "type": "line", "speaker": "福顺伯", "text": "阿梅还没下班。别坐那儿，等她回来，汤凉了她又不肯喝。"},
    {"id": "E02-S02.b09", "sourceLine": 513, "type": "line", "speaker": "旁白", "text": "林雨把纸袋抱在胸前，没有往桌边走。"},
    {"id": "E02-S02.b10", "sourceLine": 515, "type": "line", "speaker": "林雨", "text": "伯伯，我是楼下来拍楼梯的。国强说十分钟到了要看铺。我在这儿听见您叫阿梅，要不要我替您把话原样带下去？"},
    {"id": "E02-S02.b11", "sourceLine": 517, "type": "line", "speaker": "旁白", "text": "老人抬头，却像没听见“国强”。热气穿过他的肩膀。最里侧的门缝里，一个头发还在滴水的姑娘按住一叠湿掉的药钱。"},
    {"id": "E02-S02.b12", "sourceLine": 519, "type": "line", "speaker": "小梅", "text": "别叫他上来见我。你只问他：他敢不敢回来，坐在我爸面前听完一句话？他不肯，就原样说不肯。别替我求他。"},
    {"id": "E02-S02.dinner-note", "sourceLine": 521, "pickup": "dinner-note", "type": "line", "speaker": "福顺伯", "text": "阿梅那份别放凉。药钱压碗底，她嫌药苦，得拿汤顺着。"},
    {"id": "E02-S02.b13", "sourceLine": 523, "type": "line", "speaker": "林雨", "text": "我下去只问他肯不肯回来。这碗汤和药钱，不替你拿去劝他。"},
    {"id": "E02-S02.b14", "sourceLine": 525, "type": "line", "speaker": "旁白", "text": "桌底轻轻踢来一张小板凳。林雨没有接。她退到门槛，把纸袋重新抱紧。"},
    {"id": "E02-S02.b15", "sourceLine": 527, "type": "line", "speaker": "林雨", "text": "我下去问他。你那句话，我一句不添。"},
    {"id": "E02-S02.b16", "sourceLine": 529, "type": "line", "speaker": "旁白", "text": "她按约在扶手上敲三下。楼下，阿岑停了一拍，回敲三下。"}
  ]},
  "E02-S03": {"id": "E02-S03", "chapter": "E02", "title": "长子的店", "next": "E02-S04", "time": "4月4日 傍晚", "place": "门店与楼梯", "cue": "机内只有铁门和空阶；小梅只在林雨视点现身", "beats": [
    {"id": "E02-S03.b01", "sourceLine": 536, "type": "line", "speaker": "旁白", "text": "十分钟刚好走完。郑国强已经把隔壁店的卷闸拉到一半，看见林雨出来，先看她空着的手，再看阿岑还系在扶手上的绕线带。"},
    {"id": "E02-S03.b02", "sourceLine": 538, "type": "line", "speaker": "郑国强", "text": "没下去？"},
    {"id": "E02-S03.b03", "sourceLine": 540, "type": "line", "speaker": "林雨", "text": "没有。我们只在楼梯上。里面有人让我带一句话：她要你自己回去，坐在你爸面前听。她也说，你不肯，我就原样带回去。"},
    {"id": "E02-S03.b04", "sourceLine": 542, "type": "line", "speaker": "旁白", "text": "郑国强的手停在卷闸边。他没问是谁，先把闸门重新顶起一点。"},
    {"id": "E02-S03.b05", "sourceLine": 544, "type": "line", "speaker": "郑国强", "text": "老二从楼上摔下去，老三在路口撞了石墩。你要说的是阿梅，我不信她还在那儿等我。可我爸……我上个月进去过一回。他还问今晚轮到谁守着他，我一个字没答，灯一亮就跑出来了。"},
    {"id": "E02-S03.b06", "sourceLine": 546, "type": "line", "speaker": "林雨", "text": "我不能替她证明什么。我只听见她要你回来坐一会儿，不要我骗你进去。你也可以不去。"},
    {"id": "E02-S03.b07", "sourceLine": 548, "type": "line", "speaker": "旁白", "text": "国强回到收银台后，从写字台下拖出一个旧工具袋。红柄钥匙卡在一只夹层开线的儿童书包里。他拿着它站了很久，才把包重新塞回去。"},
    {"id": "E02-S03.b08", "sourceLine": 550, "type": "line", "speaker": "郑国强", "text": "我去。但我要先打电话，说我找到我爸的房间了，叫民警过来。门要开，就当着他们开；我一个人不敢再进去。"},
    {"id": "E02-S03.b09", "sourceLine": 552, "type": "line", "speaker": "阿岑", "text": "我给你留门口时间和位置，不拍你打电话。"},
    {"id": "E02-S03.b10", "sourceLine": 554, "type": "interaction", "kind": "choice", "prompt": "带上楼前，先准备哪一件事？", "options": [{"id": "E02-S03.b10.o1", "label": "请罗叔在外面辨认锁具", "sourceLine": 556, "feedback": [{"id": "E02-S03.b10.o1.f1", "type": "line", "sourceLine": 558, "speaker": "罗叔", "text": "我来只认眼前这把。铰链、锁环、门框一块儿拍进去；别看个锁头就问我谁挂的。"}, {"id": "E02-S03.b10.o1.f2", "type": "line", "sourceLine": 560, "speaker": "动作", "text": "罗叔把尺贴到门框旁，自己站在过道一侧，等国强和民警到场再看。"}]}, {"id": "E02-S03.b10.o2", "label": "和阿岑约好退路", "sourceLine": 562, "feedback": [{"id": "E02-S03.b10.o2.f1", "type": "line", "sourceLine": 564, "speaker": "阿岑", "text": "我不上楼，留在扶手这头。你敲三下，我才知道你是你；我也敲三下，你听见就回。听不见，我先叫人，不往里面闯。"}, {"id": "E02-S03.b10.o2.f2", "type": "line", "sourceLine": 566, "speaker": "动作", "text": "林雨把绕线带解下一半，留出能响的金属扶手。她和阿岑各敲三下，声音在空楼道里分得很清。"}]}]},
    {"id": "E02-S03.b11", "sourceLine": 568, "type": "line", "speaker": "旁白", "text": "郑国强拨通电话，先说地址，再说“我愿意开门”。他说完把手机屏幕朝下扣在柜台上。"},
    {"id": "E02-S03.b12", "sourceLine": 570, "type": "line", "speaker": "郑国强", "text": "等他们到。你们别替我叫我爸的名字。"}
  ]},
  "E02-S04": {"id": "E02-S04", "chapter": "E02", "title": "门外的锁", "next": "E02-S05", "time": "4月4日 入夜", "place": "饭厅与真实地下室门口", "cue": "现实行动先通报；空桌只留物件作声", "beats": [
    {"id": "E02-S04.b01", "sourceLine": 577, "type": "line", "speaker": "旁白", "text": "辖区民警到场后，郑国强领人走到后楼地下室。林雨只说“这里可能是失踪老人最后居住的房间”，没有说饭厅、湿发姑娘或药钱。国强用红柄钥匙开外门，阿岑在过道记下到场时间。"},
    {"id": "E02-S04.b02", "sourceLine": 579, "when": "E02-S03.b10.o1", "type": "line", "speaker": "旁白", "text": "罗叔先把铰链、锁环和鞋尖一起拍进全景，才退开让民警查看。"},
    {"id": "E02-S04.b03", "sourceLine": 581, "when": "E02-S03.b10.o2", "type": "line", "speaker": "旁白", "text": "阿岑在楼梯口敲三下。林雨从门槛外回了三下，他才继续记时。"},
    {"id": "E02-S04.b04", "sourceLine": 583, "type": "line", "speaker": "旁白", "text": "门里只有空药板、蹭在水泥上的白印，和一张落在床脚的照护簿。锁环朝着过道，屋里向外摸只会碰到一整块门板。"},
    {"id": "E02-S04.b05", "sourceLine": 585, "type": "interaction", "kind": "inspect", "prompt": "进到饭厅重叠的门槛。在同一个朝向看锁和报纸。", "options": [{"id": "E02-S04.b05.o1", "label": "核对内侧摸得到什么", "sourceLine": 587, "feedback": [{"id": "E02-S04.b05.o1.f1", "type": "line", "sourceLine": 589, "speaker": "林雨", "text": "我站在床边，手伸直才到门缝。罗叔，锁眼在你那面？"}, {"id": "E02-S04.b05.o1.f2", "type": "line", "sourceLine": 591, "speaker": "罗叔", "text": "对。这个朝向只说明现在锁环在外头；哪天扣的、谁扣的，我没见过。"}]}, {"id": "E02-S04.b05.o2", "label": "让国强认照护簿的日期", "sourceLine": 593, "feedback": [{"id": "E02-S04.b05.o2.f1", "type": "line", "sourceLine": 595, "speaker": "郑国强", "text": "这个月三十一天，我只写到三十。往前翻，三个整月都少一天。我在店里一次填完的。"}]}]},
    {"id": "E02-S04.b06", "sourceLine": 597, "type": "line", "speaker": "旁白", "text": "林雨把照护簿推回国强手边，转身朝民警指了指门环。"},
    {"id": "E02-S04.b07", "sourceLine": 599, "type": "line", "speaker": "林雨", "text": "这个锁在门外。簿子的日子，他自己认。别的我说不出来。"},
    {"id": "E02-S04.b08", "sourceLine": 601, "type": "line", "speaker": "旁白", "text": "饭厅在她余光里亮了一下。国平那把空椅蹭响，国安面前的碗被扣成朝下。小梅站在红柄钥匙旁，没看国强。现实的锁环留在画面前景；林雨一回头，饭厅的碗才在远处翻扣。", "pages": ["饭厅在她余光里亮了一下。国平那把空椅蹭响，国安面前的碗被扣成朝下。小梅站在红柄钥匙旁，没看国强。", "现实的锁环留在画面前景；林雨一回头，饭厅的碗才在远处翻扣。"]},
    {"id": "E02-S04.b09", "sourceLine": 603, "type": "line", "speaker": "小梅", "text": "爸，哥们都在。今天你还给他留大的？"},
    {"id": "E02-S04.b10", "sourceLine": 605, "type": "line", "speaker": "福顺伯", "text": "他抢惯了，先拿走，别压坏你的。"},
    {"id": "E02-S04.b11", "sourceLine": 607, "type": "line", "speaker": "小梅", "text": "你每回都这样。"},
    {"id": "E02-S04.b12", "sourceLine": 609, "type": "line", "speaker": "福顺伯", "text": "我分完了。你们有话自己说，别拿我的话替谁答。"},
    {"id": "E02-S04.b13", "sourceLine": 611, "type": "line", "speaker": "旁白", "text": "国强跪到现实门槛外，手没有越过那道白印。"},
    {"id": "E02-S04.b14", "sourceLine": 613, "type": "line", "speaker": "郑国强", "text": "门是我锁的。卖楼的人要我证明他没住在这里，我拿那本假簿子应了两头。我知道他还在里边。"},
    {"id": "E02-S04.b15", "sourceLine": 615, "type": "line", "speaker": "旁白", "text": "林雨等了两秒，才把手机放低。"},
    {"id": "E02-S04.b16", "sourceLine": 617, "type": "line", "speaker": "林雨", "text": "外面的人在。你愿不愿意把这句话再说一遍？不愿意，我只写我亲眼看见的锁。"},
    {"id": "E02-S04.b17", "sourceLine": 619, "type": "line", "speaker": "旁白", "text": "郑国强看向民警，点头。"},
    {"id": "E02-S04.b18", "sourceLine": 621, "type": "line", "speaker": "郑国强", "text": "我自己说。"},
    {"id": "E02-S04.b19", "sourceLine": 623, "type": "line", "speaker": "旁白", "text": "国强扶着墙站起来，先给隔壁看铺的人拨电话：“今晚我不过去了，卷闸你替我拉到底。”他说完才把手机交给民警，仍没跨过那道白印。"},
    {"id": "E02-S04.b20", "sourceLine": 625, "type": "line", "speaker": "旁白", "text": "红柄钥匙从小梅手里落到水泥上，响了一声就停。她让开通往楼梯的路。"}
  ]},
  "E02-S05": {"id": "E02-S05", "chapter": "E02", "title": "有人还能作证", "next": "E03-S01", "time": "4月5日至4月12日", "place": "302与郑家巷口", "cue": "人声录音回放清晰；现实手续用日期跳切", "beats": [
    {"id": "E02-S05.b01", "sourceLine": 632, "type": "line", "speaker": "旁白", "text": "4月5日，郑国强把照护簿扣在302的剪辑桌上，自己坐在门边。林雨把录音条拉到尽头，手指停在导出键上。"},
    {"id": "E02-S05.keeper", "sourceLine": 634, "pickup": "keeper", "type": "line", "speaker": "郑国强", "text": "簿子我带去给民警。别再让它进你们节目；我拿它骗过一次人。"},
    {"id": "E02-S05.b02", "sourceLine": 636, "type": "line", "speaker": "林雨", "text": "那别放我桌上。你自己带走。我只记你今天说的，不替你剪成好听的话。"},
    {"id": "E02-S05.return-binder", "sourceLine": 638, "pickup": "return-binder", "type": "line", "speaker": "旁白", "text": "林雨把照护簿推回他手边。国强把它塞进外套里，没有再看剪辑桌。"},
    {"id": "E02-S05.b03", "sourceLine": 640, "type": "line", "speaker": "旁白", "text": "4月12日，家属带来收件回执和初步检验摘录。林雨念到“棉絮、鼠药诱饵碎屑”便停住，把纸折回原样。"},
    {"id": "E02-S05.b04", "sourceLine": 642, "type": "line", "speaker": "林雨", "text": "我看见的是外面的锁。别的等你们和办案的人说清。"},
    {"id": "E02-S05.b05", "sourceLine": 644, "type": "set", "text": "郑家私人核对材料", "record": "zheng", "scope": "private", "holder": "郑家", "detail": "自述及初步检验只供私下核对，家属保管回执。"},
    {"id": "E02-S05.b06", "sourceLine": 646, "type": "line", "speaker": "旁白", "text": "她回到郑家门口，只带四个新包。饭厅在门里亮起短短一瞬：小梅揪走大哥包子尖上的面皮，伸手接住父亲端不稳的汤。国强在门槛外也伸了一下手。他没接着汤，手慢慢垂了下去。"},
    {"id": "E02-S05.b07", "sourceLine": 648, "type": "line", "speaker": "小梅", "text": "你以后要写那顿饭，别说他胃口好。他牙松了，咬硬的疼。"},
    {"id": "E02-S05.b08", "sourceLine": 650, "type": "line", "speaker": "旁白", "text": "林雨在手机的旁白草稿里删掉“胃口很好”，改成“他把包子放凉了”。她把屏幕转给小梅看。"},
    {"id": "E02-S05.b09", "sourceLine": 652, "type": "line", "speaker": "林雨", "text": "这样行不行？"},
    {"id": "E02-S05.b10", "sourceLine": 654, "type": "line", "speaker": "旁白", "text": "小梅看了很久，才把最小的包子往自己那边拖了一点。"},
    {"id": "E02-S05.b11", "sourceLine": 656, "type": "line", "speaker": "小梅", "text": "瘦的。下回别买错。"},
    {"id": "E02-S05.b12", "sourceLine": 658, "type": "line", "speaker": "旁白", "text": "门合上。林雨走到巷口，阿岑正在给沈嘉回电话。"},
    {"id": "E02-S05.b13", "sourceLine": 660, "type": "line", "speaker": "沈嘉", "text": "郑家的事别带到这边来。我只是做旧栏目授权清点，想到一段拍在星火网吧的采访。原采访的陈姐肯不肯见你们，得你们自己问；她的电话我先转接，不把旧带交给你们。"},
    {"id": "E02-S05.back-at-twelve", "sourceLine": 662, "pickup": "back-at-twelve", "type": "line", "speaker": "旁白", "text": "他们从郑家楼出来，沿原路走回十二号。林雨把那张票放在三〇二的桌角，外套还没脱，先听见屋里「嗒」了一声。"},
    {"id": "E02-S05.b14", "sourceLine": 664, "type": "line", "speaker": "旁白", "text": "302的旧电视里，鼠标一下下撞着桌沿。林雨看着小票背面的郑家地址被雨水洇开，拿起外套。"},
    {"id": "E02-S05.b15", "sourceLine": 666, "type": "line", "speaker": "林雨", "text": "等陈姐方便了，咱们先听她说。她不点头，十七号机就只看到门口。"}
  ]},
  "E03-S01": {"id": "E03-S01", "chapter": "E03", "title": "十七号开机", "next": "E03-S02", "time": "4月16日 夜", "place": "星火网吧", "cue": "机排深处一盏蓝灯；旧招牌已断电", "beats": [
    {"id": "E03-S01.b01", "sourceLine": 677, "type": "line", "speaker": "旁白", "text": "四天后，陈姐回了信。沈嘉把电话转过去，阿岑开着免提。那头先传来两只磁带盒碰在一起的声响。"},
    {"id": "E03-S01.b02", "sourceLine": 679, "type": "line", "speaker": "陈姐", "text": "带子在我手里。想找梁安那晚的人，你们先去问；见到朋友，我再当面问他们肯不肯听。"},
    {"id": "E03-S01.b03", "sourceLine": 681, "type": "line", "speaker": "旁白", "text": "林雨按掉免提，没有把旧节目给梁安写的“少年班神童”念出来。"},
    {"id": "E03-S01.b04", "sourceLine": 683, "type": "line", "speaker": "老邓", "text": "我把楼租给人放货了。十七号机还在，搬它费腰。半个钟头；多一分，你们帮我点一箱货。"},
    {"id": "E03-S01.b05", "sourceLine": 685, "type": "line", "speaker": "阿岑", "text": "我们只看十七号。不动别的机子。"},
    {"id": "E03-S01.b06", "sourceLine": 687, "type": "line", "speaker": "旁白", "text": "老邓领他们穿过盖着防尘布的机排。阿岑蹲下看主机插头，积灰的插脚没有插进墙。林雨所见的最深处，一盏显示器自己亮起来；穿大西服的男孩先把隔壁椅子踢远。", "pages": ["老邓领他们穿过盖着防尘布的机排。阿岑蹲下看主机插头，积灰的插脚没有插进墙。", "林雨所见的最深处，一盏显示器自己亮起来；穿大西服的男孩先把隔壁椅子踢远。"]},
    {"id": "E03-S01.b07", "sourceLine": 689, "type": "line", "speaker": "梁安", "text": "坐这把。那把腿松，我朋友一坐准翻。"},
    {"id": "E03-S01.b08", "sourceLine": 691, "type": "line", "speaker": "旁白", "text": "林雨没有立刻坐下。阿岑正伸手接住向后滑的空椅，椅背擦地的声音又短又尖。"},
    {"id": "E03-S01.b09", "sourceLine": 693, "type": "line", "speaker": "阿岑", "text": "这把真松。你看见谁动它？"},
    {"id": "E03-S01.b10", "sourceLine": 695, "type": "line", "speaker": "林雨", "text": "我看见一个男孩。他让人坐稳。"},
    {"id": "E03-S01.b11", "sourceLine": 697, "type": "line", "speaker": "林雨", "text": "陈姐有一段旧带。她说要先问过你们朋友，才让人听。"},
    {"id": "E03-S01.b12", "sourceLine": 699, "type": "line", "speaker": "梁安", "text": "那是她的带子。先别拿“神童”来问我。你先问胖虎，他们等到几点；他要是说只等了五分钟，我就知道他又在胡扯。"},
    {"id": "E03-S01.b13", "sourceLine": 701, "type": "line", "speaker": "旁白", "text": "梁安把脚抵住那把松椅，像替谁占着座位。"},
    {"id": "E03-S01.b14", "sourceLine": 703, "type": "line", "speaker": "梁安", "text": "我这儿往上翻，全是最后那几行。你回来，再问我别的。"},
    {"id": "E03-S01.wait-for", "sourceLine": 705, "pickup": "wait-for", "type": "line", "speaker": "林雨", "text": "我先找那晚的人。找不齐也回来告诉你，不拿别人的话给你凑答案。"},
    {"id": "E03-S01.b15", "sourceLine": 707, "type": "line", "speaker": "旁白", "text": "老邓在过道尽头咳了一声，指了指腕表。林雨朝十七号机点头，往铁梯退了一步。那盏蓝光没有跟着熄。"}
  ]},
  "E03-S02": {"id": "E03-S02", "chapter": "E03", "title": "答应过的十分钟", "next": "E03-S03", "time": "4月16日 深夜", "place": "网吧异境与家门", "cue": "林雨可见纸面；相机看到合着的旧本；无追逐倒计时", "beats": [
    {"id": "E03-S02.b01", "sourceLine": 714, "type": "line", "speaker": "旁白", "text": "蓝光从铁梯的踏面一路爬到她鞋尖。她低头，看见屏幕反光不再是楼梯，而是一张孩子的书桌：每道题都打了勾，“做完玩十分钟”写了三次，日期也被改过三次。她伸手扶住冰凉的栏杆，栏杆在手下变成一道关着的门；门外有人催里面把字写清楚。", "pages": ["蓝光从铁梯的踏面一路爬到她鞋尖。她低头，看见屏幕反光不再是楼梯，而是一张孩子的书桌：每道题都打了勾，“做完玩十分钟”写了三次，日期也被改过三次。", "她伸手扶住冰凉的栏杆，栏杆在手下变成一道关着的门；门外有人催里面把字写清楚。"]},
    {"id": "E03-S02.b02", "sourceLine": 716, "type": "line", "speaker": "梁安", "text": "上回我写完，也没人说我能出门。你别扯门把；外面会以为是我又不肯写。"},
    {"id": "E03-S02.b03", "sourceLine": 718, "type": "line", "speaker": "旁白", "text": "林雨蹲在门边，先把自己的手机扣在地上。"},
    {"id": "E03-S02.b04", "sourceLine": 720, "type": "line", "speaker": "林雨", "text": "门还在你手里。你要我守在这儿，就敲两下；你想一个人待着，我现在退到铁梯口。"},
    {"id": "E03-S02.b05", "sourceLine": 722, "type": "interaction", "kind": "choice", "prompt": "怎样让门里的人知道你还在？", "options": [{"id": "E03-S02.b05.o1", "label": "在门底轻碰两下", "sourceLine": 724, "feedback": [{"id": "E03-S02.b05.o1.f1", "type": "line", "sourceLine": 726, "speaker": "动作", "text": "林雨用指节碰两下门板。里面停了一会儿，也回两下；门外催作业的声音没有跟上这个节奏。"}, {"id": "E03-S02.b05.o1.f2", "type": "line", "sourceLine": 728, "speaker": "梁安", "text": "这个只有我和你听见。你明天先问老邓：那晚他们等到几点。别问他我为什么没去，他不知道。"}, {"id": "E03-S02.b05.o1.f3", "type": "line", "sourceLine": 730, "speaker": "动作", "text": "林雨在手账写下“先问老邓：等到几点”，把笔尖压进纸里。"}]}, {"id": "E03-S02.b05.o2", "label": "坐在门边等他先开口", "sourceLine": 732, "feedback": [{"id": "E03-S02.b05.o2.f1", "type": "line", "sourceLine": 734, "speaker": "动作", "text": "林雨坐到门槛外，没碰门。里面的呼吸从两短一长慢下来，一根手指从门缝探出，又蜷回去。"}, {"id": "E03-S02.b05.o2.f2", "type": "line", "sourceLine": 736, "speaker": "梁安", "text": "半糖、胖虎、过弯、木头。你先把名字找全。要是他们骂我，别替他们改。"}, {"id": "E03-S02.b05.o2.f3", "type": "line", "sourceLine": 738, "speaker": "动作", "text": "林雨在手账写下四个名字，在每个名字旁留一格空白，没有写“谁对谁错”。"}]}]},
    {"id": "E03-S02.b06", "sourceLine": 740, "type": "line", "speaker": "林雨", "text": "我今晚找人。找不齐也回这儿说一声。那把好的你别替我占太久。"},
    {"id": "E03-S02.b07", "sourceLine": 742, "type": "line", "speaker": "梁安", "text": "你坐裂的。谁叫你刚才笑。"},
    {"id": "E03-S02.b08", "sourceLine": 744, "type": "line", "speaker": "旁白", "text": "阿岑在现实的过道敲三声，林雨回敲。蓝光退回显示器里，男孩已经听不见。老邓端着半杯凉茶，在门口等他们。"},
    {"id": "E03-S02.b09", "sourceLine": 746, "type": "line", "speaker": "老邓", "text": "你俩真要找几个已经上班的孩子？先说好，店名我给你们，电话没有。"},
    {"id": "E03-S02.b10", "sourceLine": 748, "type": "line", "speaker": "林雨", "text": "给店名就够。我们一个个问，谁不见就不把谁拖回来。"}
  ]},
  "E03-S03": {"id": "E03-S03", "chapter": "E03", "title": "四十二分钟", "next": "E03-S04", "time": "4月17日至18日 白天", "place": "修鞋档与旧网吧柜台", "cue": "实名流水屏蔽他人栏；现实账页能拍", "beats": [
    {"id": "E03-S03.b01", "sourceLine": 755, "when": "E03-S02.b05.o1", "type": "line", "speaker": "旁白", "text": "老邓先把旧上机簿摊在柜台上。他指着梁安最后一次结账的那格，等林雨自己抄完才合上。"},
    {"id": "E03-S03.b02", "sourceLine": 757, "when": "E03-S02.b05.o2", "type": "line", "speaker": "旁白", "text": "林雨先照手账去了半糖的茶饮铺。半糖说胖虎正在卸货，木头保着旧盘，过弯的最后一单九点前送完；她答应晚一点一起去问老邓。"},
    {"id": "E03-S03.b03", "sourceLine": 759, "type": "line", "speaker": "旁白", "text": "傍晚，老邓才把账簿再拿出来。梁安最后一次结账四十二分钟；网吧关机以后，四个孩子挤在前台等到两点。这是老邓亲眼所见，不是他替谁补的理由。"},
    {"id": "E03-S03.b04", "sourceLine": 761, "type": "line", "speaker": "老邓", "text": "这两样别抄成一回事。四十二分钟是机器记的；等到打烊，是我看见的。后来他为什么没回来，我不知道。"},
    {"id": "E03-S03.b05", "sourceLine": 763, "type": "line", "speaker": "旁白", "text": "林雨把“四十二分钟”写在票根背面，折住另外半张空白。她把那张纸递给阿岑看，阿岑只在“等到打烊”下面划了一道线。"},
    {"id": "E03-S03.turn-to-stalls", "sourceLine": 765, "pickup": "turn-to-stalls", "type": "line", "speaker": "旁白", "text": "老邓看见票根上的名字，叫住已经下楼的两个人：「想知道他那身西服怎么回事，去老生意街找黄姨。就桥头那排铺，补鞋的隔壁。」"},
    {"id": "E03-S03.b06", "sourceLine": 767, "type": "line", "speaker": "旁白", "text": "出了网吧，林雨顺着茶铺外的路走到桥头。陈伯从修鞋档探出头，把一只补过的童鞋摆在塑料凳上。"},
    {"id": "E03-S03.b07", "sourceLine": 769, "type": "line", "speaker": "陈伯", "text": "这只我补过两回。椅子高，他后跟老磕那根铁管。鞋你拍，脸别拍，我一会儿还得吃饭。"},
    {"id": "E03-S03.b08", "sourceLine": 771, "type": "line", "speaker": "旁白", "text": "隔壁缝纫机停了一下。陈伯拿鞋往左指，黄姨正拎着一截松线往这边看。"},
    {"id": "E03-S03.b09", "sourceLine": 773, "type": "line", "speaker": "黄姨", "text": "西服是大人码，肩上空得能塞衣架。跟拍那伙人叫我把袖子缝长一点，我留了两针，回来好拆。你们找他哪件事？"},
    {"id": "E03-S03.b10", "sourceLine": 775, "type": "line", "speaker": "阿岑", "text": "想知道片子在他抬头以后剪掉什么。不是替节目定他的名字。"},
    {"id": "E03-S03.b11", "sourceLine": 777, "type": "interaction", "kind": "inspect", "prompt": "核对网上三版采访是不是三位证人。", "options": [{"id": "E03-S03.b11.o1", "label": "按掉笔声同步三个视频", "sourceLine": 779, "feedback": [{"id": "E03-S03.b11.o1.f1", "type": "line", "sourceLine": 781, "speaker": "声画", "text": "三版画幅、标题都不同；同一支笔落到同一块地砖，画面都在梁安抬头时切走。"}]}, {"id": "E03-S03.b11.o2", "label": "按袖口的两针和镜边破损对齐", "sourceLine": 783, "feedback": [{"id": "E03-S03.b11.o2.f1", "type": "line", "sourceLine": 785, "speaker": "声画", "text": "松线、缺角都在同一处。三段来自同一条采访；剪口后发生什么，账本和剪辑都答不出来。"}]}]},
    {"id": "E03-S03.meet-editor", "sourceLine": 787, "pickup": "meet-editor", "type": "line", "speaker": "旁白", "text": "门帘响了。来人穿着雨衣，腋下夹着个旧拉链包。「哪位是林雨？我是陈姐。沈嘉打电话说你们在这儿。」黄姨把店后那张小桌腾给她。"},
    {"id": "E03-S03.b12", "sourceLine": 789, "type": "line", "speaker": "旁白", "text": "陈姐从包里拿出原带，自己按下播放。父亲替梁安扣衣领的画面播完，画面先黑了，麦克风还收着声。"},
    {"id": "E03-S03.b13", "sourceLine": 791, "type": "line", "speaker": "旧带·梁安", "text": "都拍完了吧？今天能不能让我不当神童？就今天。那件衣服扎我脖子。"},
    {"id": "E03-S03.b14", "sourceLine": 793, "type": "line", "speaker": "旁白", "text": "陈姐按停，手仍压在播放器上。"},
    {"id": "E03-S03.b15", "sourceLine": 795, "type": "line", "speaker": "陈姐", "text": "这句是他活着那天说的。谁能听，由我和那几个朋友定。你们若要找他们，我可以当面问；不要拿去做预告。"},
    {"id": "E03-S03.b16", "sourceLine": 797, "type": "line", "speaker": "林雨", "text": "我只抄时码，拿着它问谁愿意坐下来。带子留在您手里。"},
    {"id": "E03-S03.b17", "sourceLine": 799, "type": "set", "text": "旧采访的私听许可", "record": "interview", "scope": "private", "holder": "陈姐／四位朋友", "detail": "陈姐保管原带。旧采访只准给朋友听，账号、截图和孩子的声音不公开。"},
    {"id": "E03-S03.b18", "sourceLine": 801, "type": "line", "speaker": "旁白", "text": "陈姐把播放器收进包。黄姨朝茶饮铺的方向指了一下。"},
    {"id": "E03-S03.b19", "sourceLine": 803, "type": "line", "speaker": "黄姨", "text": "胖虎卸完货该回来了。你们去之前先吃口东西，别把问话问成审人。"}
  ]},
  "E03-S04": {"id": "E03-S04", "chapter": "E03", "title": "四个活人", "next": "E03-S05", "time": "4月19日 下班后", "place": "茶饮铺与铁梯", "cue": "线下看本地存档；头盔、杯套、旧盘对到四人", "beats": [
    {"id": "E03-S04.b01", "sourceLine": 810, "type": "line", "speaker": "旁白", "text": "半糖收到黄姨托人带来的话，只回了一个“来”。她关了半扇茶饮铺的门，胖虎把送错的冰拎回来晾在椅背；木头抱着旧盘站在檐下；过弯发来语音，说还有一单，九点前能不能赶回看他自己。"},
    {"id": "E03-S04.b02", "sourceLine": 812, "type": "line", "speaker": "林雨", "text": "十七号机里有人问：你们那晚等到几点？"},
    {"id": "E03-S04.b03", "sourceLine": 814, "type": "line", "speaker": "旁白", "text": "胖虎没接茶，先把湿外卖袋往椅背上一甩。"},
    {"id": "E03-S04.b04", "sourceLine": 816, "type": "line", "speaker": "胖虎", "text": "等到打烊。我还骂了，朝老板骂的。我以为他考上少年班就不肯跟咱们坐。我嘴臭，别替我擦。"},
    {"id": "E03-S04.b05", "sourceLine": 818, "type": "line", "speaker": "旁白", "text": "半糖把一杯没封口的茶推给胖虎，手指在桌底敲了两下。"},
    {"id": "E03-S04.b06", "sourceLine": 820, "type": "line", "speaker": "半糖", "text": "以前上铁梯，第一个到的就这么叫后头的人跟上。梁安还记得？"},
    {"id": "E03-S04.b07", "sourceLine": 822, "type": "line", "speaker": "林雨", "text": "记得。他就是这么让我找你们的。"},
    {"id": "E03-S04.b08", "sourceLine": 824, "type": "line", "speaker": "旁白", "text": "木头这才把旧盘从包里拿出来，说聊天记录在里面。"},
    {"id": "E03-S04.b09", "sourceLine": 826, "type": "line", "speaker": "旁白", "text": "木头把旧盘里的聊天记录点开。四个人等人的消息都在；梁安反复看见的“你个废物”，这份记录里没有发送人。"},
    {"id": "E03-S04.b10", "sourceLine": 828, "type": "line", "speaker": "木头", "text": "我只能给你们在这儿看。现在的号别搜，旧盘也不上传。"},
    {"id": "E03-S04.b11", "sourceLine": 830, "type": "line", "speaker": "阿岑", "text": "今晚收工咱们一起去。我去找把扳手。梁安给我留的那把椅子，一坐就晃。你们谁愿意来，谁就坐；不愿意，留下话也行。"},
    {"id": "E03-S04.b12", "sourceLine": 832, "type": "line", "speaker": "半糖", "text": "我十点半得回去冻明天的料。够我走一趟；我不在镜头里说。"},
    {"id": "E03-S04.b13", "sourceLine": 834, "type": "line", "speaker": "旁白", "text": "过弯的电动车在茶铺前冲过，又刹回来。他没摘头盔，只把配送箱往墙边一靠。"},
    {"id": "E03-S04.b14", "sourceLine": 836, "type": "line", "speaker": "过弯", "text": "最后一单我转出去了。今晚去，省得明天又有人等我。"},
    {"id": "E03-S04.b15", "sourceLine": 838, "type": "line", "speaker": "旁白", "text": "半糖替他扣正护目镜。胖虎把湿袋拎起来，木头把旧盘塞回胸前口袋。四个人不是同时点头，却一起往铁梯走。"}
  ]},
  "E03-S05": {"id": "E03-S05", "chapter": "E03", "title": "五把椅子", "next": "E04-S01", "time": "4月19日 近零点", "place": "星火网吧", "cue": "四位朋友与十七号空椅始终在同一眼高构图；林雨所见的梁安只叠入空椅旁，机内回放不给录像补画鬼", "beats": [
    {"id": "E03-S05.b01", "sourceLine": 845, "type": "line", "speaker": "旁白", "text": "五把椅子，来了四个人。靠门的还撑着椅背等木头开机。没人去抢正中十七号机前那把，它底下有颗螺帽松了，一碰就晃。木头把旧盘放进电脑，当年的房间又亮了。阿岑蹲到空椅边摸了摸，把一路带来的扳手搁在脚边。"},
    {"id": "E03-S05.b02", "sourceLine": 847, "type": "line", "speaker": "胖虎", "text": "那晚我们等到打烊。我后来那句气话，不该让你一个人看见。"},
    {"id": "E03-S05.b03", "sourceLine": 849, "type": "line", "speaker": "旁白", "text": "过弯把饮料从键盘旁挪远，才朝那张空椅子开口。"},
    {"id": "E03-S05.b04", "sourceLine": 851, "type": "line", "speaker": "过弯", "text": "你垫我三块五，我一直记着。"},
    {"id": "E03-S05.b05", "sourceLine": 853, "type": "line", "speaker": "旁白", "text": "林雨看向十七号机：梁安坐到那把空椅旁，抬眼看过弯；椅面仍空着。"},
    {"id": "E03-S05.b06", "sourceLine": 855, "type": "line", "speaker": "梁安", "text": "四块。五毛钱让他说没了。"},
    {"id": "E03-S05.b07", "sourceLine": 857, "type": "interaction", "kind": "choice", "prompt": "让四个人怎么收到这句话？", "options": [{"id": "E03-S05.b07.o1", "label": "替他逐字带话，由梁安按开始", "sourceLine": 859, "feedback": [{"id": "E03-S05.b07.o1.f1", "type": "line", "sourceLine": 861, "speaker": "林雨", "text": "他说，是四块。少的五毛他也记着。还有——他问你们，能不能把这局打完。"}, {"id": "E03-S05.b07.o1.f2", "type": "line", "sourceLine": 863, "speaker": "动作", "text": "过弯摸出四枚硬币，压在键盘角。林雨没有替梁安点开始；十七号机前的手自己按下按键。"}]}, {"id": "E03-S05.b07.o2", "label": "先让大家安静，让旧鼠标自己响", "sourceLine": 865, "feedback": [{"id": "E03-S05.b07.o2.f1", "type": "line", "sourceLine": 867, "speaker": "动作", "text": "第五只鼠标响四下。过弯把三块五一枚枚数到四块，最后一枚放下时，鼠标停住。"}, {"id": "E03-S05.b07.o2.f2", "type": "line", "sourceLine": 869, "speaker": "动作", "text": "梁安从空位伸手按下开始。胖虎没有追问是谁动的鼠标，只把耳机递向空椅。"}]}]},
    {"id": "E03-S05.first-round", "sourceLine": 871, "pickup": "first-round", "type": "line", "speaker": "旁白", "text": "开局的提示音一响，半糖左手已经移到从前的那几个键。胖虎忘了自己换过位置，朝空椅那边喊：「回来！你后头有一个。」"},
    {"id": "E03-S05.old-call", "sourceLine": 873, "pickup": "old-call", "type": "line", "speaker": "过弯", "text": "你冲我嚷什么，我现在坐你左手边。"},
    {"id": "E03-S05.fifth-button", "sourceLine": 875, "pickup": "fifth-button", "type": "line", "speaker": "旁白", "text": "胖虎怔了一下。十七号的鼠标轻轻响了两下。屏幕里那个快掉队的小人回过头，跟上了他们。"},
    {"id": "E03-S05.last-round", "sourceLine": 877, "pickup": "last-round", "type": "line", "speaker": "半糖", "text": "他听到了。胖子，看你自己那边！"},
    {"id": "E03-S05.last-minute", "sourceLine": 879, "pickup": "last-minute", "type": "line", "speaker": "旁白", "text": "最后半分钟，林雨也没再帮谁传话。从她这儿看，五个人全盯着同一片光。阿岑只拍到四副肩膀同时往前倾了一下。"},
    {"id": "E03-S05.b08", "sourceLine": 881, "type": "line", "speaker": "旁白", "text": "结算提示响了一声。他们输了一分。音乐停了，谁也没点退出。过弯把手从鼠标上拿开，朝那把空椅偏过头。四个人都还在。", "pages": ["结算提示响了一声。他们输了一分。音乐停了，谁也没点退出。", "过弯把手从鼠标上拿开，朝那把空椅偏过头。四个人都还在。"]},
    {"id": "E03-S05.b09", "sourceLine": 883, "type": "line", "speaker": "旁白", "text": "梁安把旧卡推到柜台前，脱下那件不合身的西服，里面是领口褪白的球衣。"},
    {"id": "E03-S05.b10", "sourceLine": 885, "type": "line", "speaker": "梁安", "text": "这件还给陈姐。别让她又拿去给人拍。"},
    {"id": "E03-S05.b11", "sourceLine": 887, "type": "line", "speaker": "老邓", "text": "卡我收着。照片卷角不是我弄的。"},
    {"id": "E03-S05.b12", "sourceLine": 889, "type": "line", "speaker": "旁白", "text": "林雨把西服搭在十七号机的椅背上，等陈姐来取。阿岑蹲下去，拧紧那把松椅的螺帽。轮子落稳了，梁安才把自己坐惯的那把好椅往阿岑脚边推。", "pages": ["林雨把西服搭在十七号机的椅背上，等陈姐来取。阿岑蹲下去，拧紧那把松椅的螺帽。", "轮子落稳了，梁安才把自己坐惯的那把好椅往阿岑脚边推。"]},
    {"id": "E03-S05.b13", "sourceLine": 891, "type": "line", "speaker": "梁安", "text": "你坐。下回别接人家摔下来的椅子。"},
    {"id": "E03-S05.b14", "sourceLine": 893, "type": "line", "speaker": "旁白", "text": "他朝四个人抬了下手，退出了屏幕。聊天框最后只留“都怪你”四个字，没有人认得谁敲的。林雨看了一眼，没有把它读出来。"},
    {"id": "E03-S05.friends.1", "sourceLine": 895, "pickup": "friends.1", "type": "line", "speaker": "旁白", "text": "阿岑停机，倒回最后一局。小屏幕上，四个人一块儿往前倾，十七号椅上空着。进度条到了散场那会儿。椅背上多了一件灰西服，四个人都朝它转过脸。把这几秒再放一遍，仍然看不到梁安。", "pages": ["阿岑停机，倒回最后一局。小屏幕上，四个人一块儿往前倾，十七号椅上空着。", "进度条到了散场那会儿。椅背上多了一件灰西服，四个人都朝它转过脸。把这几秒再放一遍，仍然看不到梁安。"]},
    {"id": "E03-S05.b15", "sourceLine": 897, "type": "line", "speaker": "阿岑", "text": "这段留不留？留给谁，你们定。"},
    {"id": "E03-S05.b16", "sourceLine": 899, "type": "line", "speaker": "半糖", "text": "留给我们。别发频道。下次谁又忙到不回消息，拿出来骂他两句也好。"},
    {"id": "E03-S05.b17", "sourceLine": 901, "type": "line", "speaker": "旁白", "text": "阿岑把刚才那局拷进电脑。木头取出自己的旧盘，换上空白盘。光驱响了一阵，写好了。胖虎在新盘上签了旧外号，过弯补上日期。半糖把它收进外卖袋最里面。木头拍了拍胸前的口袋，他那张旧的也还在。", "pages": ["阿岑把刚才那局拷进电脑。木头取出自己的旧盘，换上空白盘。光驱响了一阵，写好了。", "胖虎在新盘上签了旧外号，过弯补上日期。半糖把它收进外卖袋最里面。木头拍了拍胸前的口袋，他那张旧的也还在。"]},
    {"id": "E03-S05.b18", "sourceLine": 903, "type": "line", "speaker": "胖虎", "text": "下周我休半天。茶铺关门以后，来喝一杯。不是采访。"},
    {"id": "E03-S05.b19", "sourceLine": 905, "type": "line", "speaker": "旁白", "text": "林雨把相机盖合上。"},
    {"id": "E03-S05.b20", "sourceLine": 907, "type": "line", "speaker": "林雨", "text": "不是采访。我带人来，也先问你们坐不坐。"},
    {"id": "E03-S05.b21", "sourceLine": 909, "type": "line", "speaker": "旁白", "text": "老邓靠在柜台后，等他们各自把椅子推回去。"},
    {"id": "E03-S05.b22", "sourceLine": 911, "type": "line", "speaker": "老邓", "text": "能传的只有我这句：那天前台有四个人，等他到打烊。我姓邓，我自己说。"},
    {"id": "E03-S05.b23", "sourceLine": 913, "type": "set", "text": "老邓准许公开的证言", "record": "deng", "scope": "public", "holder": "老邓", "detail": "可播本人亲见的等候和经许可的上机时长。"},
    {"id": "E03-S05.b24", "sourceLine": 915, "type": "line", "speaker": "旁白", "text": "他们下铁梯时，半糖拍了拍外卖袋最里面那张写好的录盘；木头把原来的旧盘按在胸前。林雨没开直播，和阿岑沿主巷走回今宵便利；粉叔正把最后一笼肠粉从蒸柜里端出来。"}
  ]},
  "E04-S01": {"id": "E04-S01", "chapter": "E04", "title": "两双筷子", "next": "E04-S02", "time": "4月26日 夜", "place": "粉摊", "cue": "蒸汽、碟底；收银叫号与蒸柜声分开", "beats": [
    {"id": "E04-S01.b01", "sourceLine": 926, "type": "line", "speaker": "旁白", "text": "一周后，胖虎把茶饮铺关早了半小时。几个人真的在门口喝完那杯，没人拿出旧盘。林雨回302交完一支婚礼精剪，带着续租的钱到粉摊吃夜宵；阿岑还在酒店收婚宴的机位。"},
    {"id": "E04-S01.b02", "sourceLine": 928, "type": "line", "speaker": "旁白", "text": "粉叔撕了两套一次性筷子。拆开的一套放在林雨碟上，另一套压在炉边。"},
    {"id": "E04-S01.b03", "sourceLine": 930, "type": "line", "speaker": "林雨", "text": "我一个人。阿岑今晚在酒店。"},
    {"id": "E04-S01.b04", "sourceLine": 932, "type": "line", "speaker": "粉叔", "text": "我数得清。高的那张凳给我留着，有个人膝盖弯不下去。"},
    {"id": "E04-S01.return-seat", "sourceLine": 934, "pickup": "return-seat", "type": "line", "speaker": "林雨", "text": "上回他们叫我来喝茶，不是采访。我吃完就回302；您要我送什么，先把规矩说给我听。"},
    {"id": "E04-S01.b05", "sourceLine": 936, "type": "line", "speaker": "旁白", "text": "林雨把凳子挪到粉叔脚边。粉叔没道谢，先把三张写得发黄的单子平码在案板上。每张都有地点，姓名和价钱那格都空着。"},
    {"id": "E04-S01.b06", "sourceLine": 938, "type": "line", "speaker": "粉叔", "text": "前两晚收摊，我看见它们压在蒸柜底下。原是夜班的人点的，三份都蒸好了；地点写着，名字和钱数空着。谁也别替人把空格填满。"},
    {"id": "E04-S01.b07", "sourceLine": 940, "type": "line", "speaker": "林雨", "text": "三份都送到地点？送不到呢？"},
    {"id": "E04-S01.b08", "sourceLine": 942, "type": "line", "speaker": "粉叔", "text": "交到肯伸手的人手里。人不肯拿，你就放回单边，不准追着问名字。"},
    {"id": "E04-S01.b09", "sourceLine": 944, "type": "line", "speaker": "旁白", "text": "粉叔把三只饭盒分进纸袋，各在袋口夹一张空回单。林雨看了一眼炉边那双没拆的筷子。"},
    {"id": "E04-S01.b10", "sourceLine": 946, "type": "line", "speaker": "林雨", "text": "这双呢？"},
    {"id": "E04-S01.b11", "sourceLine": 948, "type": "line", "speaker": "粉叔", "text": "小茵下班没准点，不是等谁。她自己来，才算她的。"},
    {"id": "E04-S01.b12", "sourceLine": 950, "type": "line", "speaker": "旁白", "text": "粉叔把第二双筷子压回炉边，没有写进任何一张旧单。"},
    {"id": "E04-S01.b13", "sourceLine": 952, "type": "line", "speaker": "旁白", "text": "摊前忽然排起十几个人。蒸笼里明明只够三份，队伍却不往前挪，只有影子朝叫号器移动。粉叔把自己的手机锁进抽屉，扭头看林雨。"},
    {"id": "E04-S01.b14", "sourceLine": 954, "type": "line", "speaker": "粉叔", "text": "你肯送，我早半个钟头收工。送完回来，别替我把账结了。"},
    {"id": "E04-S01.b15", "sourceLine": 956, "type": "line", "speaker": "旁白", "text": "林雨把自己的肠粉盖上，收条夹进纸袋。她从粉摊外绕开队伍，第一张旧单写着工棚旧址。"}
  ]},
  "E04-S02": {"id": "E04-S02", "chapter": "E04", "title": "三份旧单", "next": "E04-S03", "time": "4月27日 01:40", "place": "工棚旧址、桥底、卸货门", "cue": "三格连续画；每处手交食物，收据的空栏保留", "beats": [
    {"id": "E04-S02.b01", "sourceLine": 963, "type": "line", "speaker": "旁白", "text": "工棚旧址的风从破铁皮里钻出来。一个戴安全帽的工人坐在水泥墩上，先盯住饭盒，后盯住林雨手里的回单。"},
    {"id": "E04-S02.b02", "sourceLine": 965, "type": "line", "speaker": "工人", "text": "七十六是领钱时叫的号。我妈要来，你说七十六，她认得哪个？纸给我，我自己写。"},
    {"id": "E04-S02.b03", "sourceLine": 967, "type": "interaction", "kind": "choice", "prompt": "除了工号，还留下哪一样让家里人认得他？", "options": [{"id": "E04-S02.b03.o1", "label": "垫好复写纸，把笔让给他", "sourceLine": 969, "feedback": [{"id": "E04-S02.b03.o1.f1", "type": "line", "sourceLine": 971, "speaker": "动作", "text": "林雨垫好复写纸，把笔横放在饭盒旁。工人写下“想回来”，最后一笔戳穿薄纸；原页压回他的安全帽下，副页留在她掌心。"}, {"id": "E04-S02.b03.o1.f2", "type": "line", "sourceLine": 973, "speaker": "手机·待核袋", "text": "复写字迹／仅供亲属比对；未确认身份。"}]}, {"id": "E04-S02.b03.o2", "label": "照他指的位置描下缺瓷的饭缸", "sourceLine": 975, "feedback": [{"id": "E04-S02.b03.o2.f1", "type": "line", "sourceLine": 977, "speaker": "工人", "text": "蓝边，缺的这块像颗松牙。底下有我家的屋号，别在街上念。"}, {"id": "E04-S02.b03.o2.f2", "type": "line", "sourceLine": 979, "speaker": "动作", "text": "林雨折起写着屋号的部分，只在回单外沿描出缺瓷轮廓。"}, {"id": "E04-S02.b03.o2.f3", "type": "line", "sourceLine": 981, "speaker": "手机·待核袋", "text": "饭缸缺瓷轮廓／仅供亲属比对；工号可能被代领。"}]}]},
    {"id": "E04-S02.b04", "sourceLine": 983, "type": "line", "speaker": "旁白", "text": "林雨把蓝本合上，起身时少拎了一份，纸袋在风里轻得直打转。"},
    {"id": "E04-S02.under-bridge", "sourceLine": 985, "pickup": "under-bridge", "type": "line", "speaker": "旁白", "text": "沿铁皮围墙走到底，头顶开始有车声。桥底左边的小屋亮着灯，有人从栏杆后伸手冲她招了招。"},
    {"id": "E04-S02.b05", "sourceLine": 987, "type": "line", "speaker": "旁白", "text": "桥底的代驾把头盔摆在膝头，先把酱盒拧紧。"},
    {"id": "E04-S02.b06", "sourceLine": 989, "type": "line", "speaker": "代驾", "text": "别在单上盖“送达客人”。我在这儿歇脚睡过去，我哥找不到我。写头盔也在。"},
    {"id": "E04-S02.b07", "sourceLine": 991, "type": "line", "speaker": "林雨", "text": "只写这个歪贴纸？"},
    {"id": "E04-S02.b08", "sourceLine": 993, "type": "line", "speaker": "代驾", "text": "他给我贴正过三回，还歪。这个他认得。"},
    {"id": "E04-S02.b09", "sourceLine": 995, "type": "line", "speaker": "旁白", "text": "林雨画下贴纸的位置，把饭盒放到他够得着的栏杆上，没有写姓名。"},
    {"id": "E04-S02.dock-turn", "sourceLine": 997, "pickup": "dock-turn", "type": "line", "speaker": "旁白", "text": "林雨照着最后一张单往桥的另一头走。小路尽头，一叠红蓝货筐挡住半扇门。她敲了敲，屋里的人把筐往里拉了一点。"},
    {"id": "E04-S02.b10", "sourceLine": 999, "type": "line", "speaker": "旁白", "text": "卸货门背后，女孩用胸卡盖住手心。她够不到手机的发送键，先看林雨的镜头包。"},
    {"id": "E04-S02.b11", "sourceLine": 1001, "type": "line", "speaker": "女孩", "text": "我请病假的事，被同事拿去做培训录音。你在录吗？"},
    {"id": "E04-S02.b12", "sourceLine": 1003, "type": "line", "speaker": "林雨", "text": "手机在袋里，没开。你这份没葱，底下烫。"},
    {"id": "E04-S02.b13", "sourceLine": 1005, "type": "line", "speaker": "旁白", "text": "女孩把饭盒挪到膝头，过了一会儿才低头吃。林雨把回单姓名栏折到背面，和头盔贴纸一起放进待核袋。"},
    {"id": "E04-S02.b14", "sourceLine": 1007, "type": "line", "speaker": "手机·待核袋", "text": "歪贴纸／未填姓名／交回粉叔保管。"},
    {"id": "E04-S02.b15", "sourceLine": 1009, "type": "line", "speaker": "旁白", "text": "她最后看了一眼三处地点，才朝粉摊走。纸袋空了，叫号的声音却越来越近。"}
  ]},
  "E04-S03": {"id": "E04-S03", "chapter": "E04", "title": "多出来的活人", "next": "E04-S04", "time": "4月27日 02:15", "place": "粉摊", "cue": "队尾到队首变化以动作计；危险声可用字幕辨向", "beats": [
    {"id": "E04-S03.b01", "sourceLine": 1016, "type": "line", "speaker": "旁白", "text": "回到棚下，蓝白耳麦还在队伍里。小茵站在它前面，后跟磨破，袜口浸出一点血。她手机第三次震动，屏幕上是“换班确认”；她明明已经下班，却把手抬到耳边，等叫号器念工号。"},
    {"id": "E04-S03.b02", "sourceLine": 1018, "type": "line", "speaker": "小茵", "text": "你叫我？我跟她们说我得回去接线，没一个回头。我还以为下班了，也得等叫到工号才准走。"},
    {"id": "E04-S03.b03", "sourceLine": 1020, "type": "line", "speaker": "旁白", "text": "叫号器从七十六跳到她的工号。林雨没有碰她，只侧身挡住她往前迈的半步；侧门的灯正落在小茵手里的耳麦上。"},
    {"id": "E04-S03.b04", "sourceLine": 1022, "type": "line", "speaker": "林雨", "text": "耳麦在你手里。侧门也开着。"},
    {"id": "E04-S03.b05", "sourceLine": 1024, "type": "interaction", "kind": "choice", "prompt": "打断下一次叫号，给小茵留一个自己能做的动作。", "options": [{"id": "E04-S03.b05.o1", "label": "问她愿不愿自己摘下耳麦", "sourceLine": 1026, "feedback": [{"id": "E04-S03.b05.o1.f1", "type": "line", "sourceLine": 1028, "speaker": "小茵", "text": "我摘了就要被记离线的。……我都下班了啊。"}, {"id": "E04-S03.b05.o1.f2", "type": "line", "sourceLine": 1030, "speaker": "动作", "text": "她自己把耳麦取下，放在饭碗边。先听见蒸柜里的水烧开，才听见粉叔问她要不要加葱。"}]}, {"id": "E04-S03.b05.o2", "label": "请阿琴开侧门，让她认出回家的路", "sourceLine": 1032, "feedback": [{"id": "E04-S03.b05.o2.f1", "type": "line", "sourceLine": 1034, "speaker": "阿琴", "text": "茵茵，你昨天落在柜上那包纸巾，还要我送回去呀？"}, {"id": "E04-S03.b05.o2.f2", "type": "line", "sourceLine": 1036, "speaker": "动作", "text": "小茵回头看见侧门，自己把工牌从脖子上摘下，塞进阿琴递来的纸巾包。"}]}]},
    {"id": "E04-S03.b06", "sourceLine": 1038, "type": "line", "speaker": "旁白", "text": "粉叔把压住的两根筷子推到她手边，转身调火。林雨掀开自己那碟已经凉掉的肠粉。"},
    {"id": "E04-S03.b07", "sourceLine": 1040, "type": "line", "speaker": "小茵", "text": "你们那行，拍人出事才有钱吧？我今晚只想回去睡。有没有人要拍我这副相？"},
    {"id": "E04-S03.b08", "sourceLine": 1042, "type": "line", "speaker": "旁白", "text": "林雨把镜头包拉链拉到底，放到凳子下面。"},
    {"id": "E04-S03.b09", "sourceLine": 1044, "type": "line", "speaker": "林雨", "text": "没有。我不拍。你要不要坐下，把这碟重新蒸热？"},
    {"id": "E04-S03.b10", "sourceLine": 1046, "type": "line", "speaker": "旁白", "text": "小茵没有马上回答。"},
    {"id": "E04-S03.sit-five", "sourceLine": 1048, "pickup": "sit-five", "type": "line", "speaker": "小茵", "text": "五分钟。有人再叫我工号，你们别替我回。"},
    {"id": "E04-S03.b11", "sourceLine": 1050, "type": "line", "speaker": "旁白", "text": "她把自己的碟子叠到林雨那碟上，终于坐下。队伍退回雨棚边，刚才小茵站过的位置却多出一个端着饭盒的林雨。粉叔抬头时，林雨的碟还在矮凳上；林雨回头时，另一个自己正把下一张号举到胸前。", "pages": ["她把自己的碟子叠到林雨那碟上，终于坐下。队伍退回雨棚边，刚才小茵站过的位置却多出一个端着饭盒的林雨。", "粉叔抬头时，林雨的碟还在矮凳上；林雨回头时，另一个自己正把下一张号举到胸前。"]},
    {"id": "E04-S03.b12", "sourceLine": 1052, "type": "line", "speaker": "旁白", "text": "那个林雨举起下一张号，脸上没有眼睛，只有旧手机熄屏后留下的两点指印。"},
    {"id": "E04-S03.b13", "sourceLine": 1054, "type": "line", "speaker": "粉叔", "text": "你还差一件事。哪样？"},
    {"id": "E04-S03.b14", "sourceLine": 1056, "type": "line", "speaker": "旁白", "text": "林雨端起碟，避开那个自己，坐回矮凳。"},
    {"id": "E04-S03.b15", "sourceLine": 1058, "type": "line", "speaker": "林雨", "text": "我还没吃完。先不结账。"},
    {"id": "E04-S03.b16", "sourceLine": 1060, "type": "line", "speaker": "旁白", "text": "小茵把手机翻扣在桌面，和她一起等蒸柜重新冒气。"}
  ]},
  "E04-S04": {"id": "E04-S04", "chapter": "E04", "title": "有人来问", "next": "E05-S01", "time": "4月27日 天亮", "place": "粉摊与302", "cue": "街坊陆续上早班；手机来电可读", "beats": [
    {"id": "E04-S04.b01", "sourceLine": 1067, "type": "line", "speaker": "旁白", "text": "天亮后，粉叔把蓝本摊在案板上。林雨把待核袋里的东西一件件放回去：没选的那样、代驾的歪贴纸、没填姓名的回单。粉叔不问她在哪儿见着，只拿小铁夹夹住页码。"},
    {"id": "E04-S04.b02", "sourceLine": 1069, "type": "line", "speaker": "粉叔", "text": "哪样有人来问，哪样才拿出来。电话让人自己留给我；你只抄页码。"},
    {"id": "E04-S04.b03", "sourceLine": 1071, "when": "E04-S02.b03.o1", "type": "line", "speaker": "旁白", "text": "一个送工服的女人摸过复写上的“回”字，沉默很久。"},
    {"id": "E04-S04.b04", "sourceLine": 1073, "when": "E04-S02.b03.o1", "type": "line", "speaker": "女人", "text": "我弟写字也这样用力。我回去找他旧信比一比，比不上就还是待核。"},
    {"id": "E04-S04.b05", "sourceLine": 1075, "when": "E04-S02.b03.o2", "type": "line", "speaker": "旁白", "text": "一个送工服的女人把缺瓷轮廓看了又看。"},
    {"id": "E04-S04.b06", "sourceLine": 1077, "when": "E04-S02.b03.o2", "type": "line", "speaker": "女人", "text": "这颜色我认得，可饭缸借过人。我带回去给家里看，不急着填名字。"},
    {"id": "E04-S04.b07", "sourceLine": 1079, "type": "set", "text": "粉摊回单页码", "record": "orders", "scope": "private", "holder": "粉叔", "detail": "只记页码；家属仍在核对，姓名和夹板内的电话不对外。"},
    {"id": "E04-S04.b08", "sourceLine": 1081, "when": "E04-S03.b05.o1", "type": "line", "speaker": "旁白", "text": "耳麦还放在小茵碗边。她拎走前，用指尖碰了一下耳机线，没戴回去。"},
    {"id": "E04-S04.b09", "sourceLine": 1083, "when": "E04-S03.b05.o2", "type": "line", "speaker": "旁白", "text": "小茵的工牌还在纸巾包里。她把包塞进外套口袋，没挂回脖子上。"},
    {"id": "E04-S04.b10", "sourceLine": 1085, "type": "line", "speaker": "旁白", "text": "小茵走后，林雨把那张矮凳推回桌下。十几分钟，手机亮了一下。小茵发来一张照片，门内摆着拖鞋，插座旁的充电线露着一截铜丝。"},
    {"id": "E04-S04.b11", "sourceLine": 1087, "type": "line", "speaker": "手机·小茵", "text": "到了。这根线又断了。晚上能去你那儿借个充电宝吗？我坐会儿就走。"},
    {"id": "E04-S04.b12", "sourceLine": 1089, "type": "line", "speaker": "旁白", "text": "林雨看完，没有追问昨夜的队伍。她把302的门号发过去，又补了一句“上楼敲两下”。"},
    {"id": "E04-S04.visit.1", "sourceLine": 1091, "pickup": "visit.1", "type": "line", "speaker": "旁白", "text": "傍晚，小茵照着约定敲了两下。林雨开门前先把相机推进抽屉；桌上只有充电宝、两碗白粥和一张没剪完的婚礼时间线。"},
    {"id": "E04-S04.b13", "sourceLine": 1093, "type": "line", "speaker": "小茵", "text": "我不是来讲昨晚的。手机充到能打车就走。"},
    {"id": "E04-S04.b14", "sourceLine": 1095, "type": "line", "speaker": "林雨", "text": "好。插这儿。粥凉了就倒，不用替我吃完。"},
    {"id": "E04-S04.b15", "sourceLine": 1097, "type": "line", "speaker": "旁白", "text": "小茵坐在床边给手机充电，先看见时间线里一对新人反复走到门口，又倒回去。她指着画面里被林雨剪掉的一段空白。"},
    {"id": "E04-S04.b16", "sourceLine": 1099, "type": "line", "speaker": "小茵", "text": "这儿怎么没声？"},
    {"id": "E04-S04.b17", "sourceLine": 1101, "type": "line", "speaker": "林雨", "text": "新娘说不想把她爸哭的声音留下。我就停在她点头以前。"},
    {"id": "E04-S04.heard-enough", "sourceLine": 1103, "pickup": "heard-enough", "type": "line", "speaker": "林雨", "text": "她说停，我就停。我已经听见她爸哭过，不需要让别人也听。"},
    {"id": "E04-S04.b18", "sourceLine": 1105, "type": "line", "speaker": "旁白", "text": "小茵看了看电量，够叫车了。她拔掉线，却没立刻起身。"},
    {"id": "E04-S04.b19", "sourceLine": 1107, "type": "line", "speaker": "小茵", "text": "下回我下班，能不能还来借？不一定说话。"},
    {"id": "E04-S04.b20", "sourceLine": 1109, "type": "line", "speaker": "林雨", "text": "能。你敲两下；我在就开门，不在我会回你。"},
    {"id": "E04-S04.b21", "sourceLine": 1111, "type": "line", "speaker": "旁白", "text": "小茵把充电宝放回桌上，拿走一只空碗，走前真的只坐了五分钟。门合上后，林雨才发现她把自己的纸巾包忘在床边。"},
    {"id": "E04-S04.b22", "sourceLine": 1113, "type": "line", "speaker": "旁白", "text": "阿岑在楼下按了两声喇叭。林雨披上外套，沿楼梯下去，他还跨在电单车上，车把挂着两杯豆浆。"},
    {"id": "E04-S04.b23", "sourceLine": 1115, "type": "line", "speaker": "阿岑", "text": "周铭在酒店看了婚礼片，问《夜访》愿不愿给他试一支夜班栏目。有偿，三千六先看样片。素材得逐项问人。"},
    {"id": "E04-S04.b24", "sourceLine": 1117, "type": "line", "speaker": "旁白", "text": "林雨把名片夹进未结账的蓝本复印页里。"},
    {"id": "E04-S04.b25", "sourceLine": 1119, "type": "line", "speaker": "林雨", "text": "就约五月八号，晚上七点半。先把他说的原话听完，婚礼这单也得先交了。"}
  ]},
  "E05-S01": {"id": "E05-S01", "chapter": "E05", "title": "周三可以", "next": "E05-S02", "time": "5月8日 19:30", "place": "302剪辑桌", "cue": "真实商业试剪；手机讯息与素材回放分轨", "beats": [
    {"id": "E05-S01.b01", "sourceLine": 1130, "type": "line", "speaker": "旁白", "text": "阿岑把四段采访拖进时间线，耳机只戴一边。林雨在旁边核对授权单：谁只许试剪，谁只答应周三，谁的孩子不能入画。周铭发来的报价停在屏幕上，三千六，先看样片；镜头租金明早到期。"},
    {"id": "E05-S01.b02", "sourceLine": 1132, "type": "line", "speaker": "周铭", "text": "做夜班的人，观众一看就懂。你们把气氛接起来，客户明早看。正式发布再把材料一项项补齐。"},
    {"id": "E05-S01.b03", "sourceLine": 1134, "type": "line", "speaker": "录音·仓管员", "text": "周三我可以加班。下礼拜得接我妹，我妈回老家复查眼睛。"},
    {"id": "E05-S01.b04", "sourceLine": 1136, "type": "line", "speaker": "旁白", "text": "周铭的剪辑意见紧跟着跳出来：把这句接到清晨的空走廊，再盖一帧雨景。林雨按了暂停。耳机里尾音还没完，仓管员像是又吸了口气。"},
    {"id": "E05-S01.b05", "sourceLine": 1138, "type": "line", "speaker": "林雨", "text": "她后面还有话。先别盖。"},
    {"id": "E05-S01.b06", "sourceLine": 1140, "type": "line", "speaker": "阿岑", "text": "我听见了。可是多留几秒，就得跟周铭重新谈钱。"},
    {"id": "E05-S01.no-fill", "sourceLine": 1142, "pickup": "no-fill", "type": "line", "speaker": "林雨", "text": "钱可以谈；她没答应的那几天，不能由我拿来补气氛。先把她的话送回她自己手里。"},
    {"id": "E05-S01.b07", "sourceLine": 1144, "type": "line", "speaker": "旁白", "text": "林雨没点导出。她留着那口没说完的气，摘下耳机。她拎着衣篮上了半层楼。天台门让风抵住了，她拿肩膀轻轻顶了一下。风把一件干衬衫吹到她手边。林雨想拍张晚霞给妈妈，举起手机，镜头里只剩一排湿工装。", "pages": ["林雨没点导出。她留着那口没说完的气，摘下耳机。", "她拎着衣篮上了半层楼。天台门让风抵住了，她拿肩膀轻轻顶了一下。", "风把一件干衬衫吹到她手边。林雨想拍张晚霞给妈妈，举起手机，镜头里只剩一排湿工装。"]}
  ]},
  "E05-S02": {"id": "E05-S02", "chapter": "E05", "title": "口袋里的钟", "next": "E05-S03", "time": "5月8日 夜", "place": "楼顶绳阵", "cue": "滴水变成鼠标声；风动方向固定；没有实体坠落镜头", "beats": [
    {"id": "E05-S02.b01", "sourceLine": 1151, "type": "line", "speaker": "旁白", "text": "风把四件工装吹到她腰边。楼下窗户亮着蓝光，滴水一下一下，和剪辑鼠标的点击合到了一处。卫衣的袖口从衣架上垂下来，像有人正把光标停在“发送”上。"},
    {"id": "E05-S02.b02", "sourceLine": 1153, "type": "line", "speaker": "林雨", "text": "我来拿衣服。你要是还没想好，别让我替你按。"},
    {"id": "E05-S02.b03", "sourceLine": 1155, "type": "line", "speaker": "旁白", "text": "她在雨衣口袋摸到一张工资明细，在卫衣口袋摸到写了三遍又划掉的辞职信。手机自己亮起，正好是周铭的返单页面。四个收件人都在等回复。"},
    {"id": "E05-S02.b04", "sourceLine": 1157, "type": "interaction", "kind": "choice", "prompt": "试着替空工位处理一张返单。", "options": [{"id": "E05-S02.b04.o1", "label": "写明原采访只答应周三", "sourceLine": 1159, "feedback": [{"id": "E05-S02.b04.o1.f1", "type": "line", "sourceLine": 1161, "speaker": "屏显", "text": "林雨删掉“随时可用”，留下“仅周三”。一周七格里只亮着一天，袖口慢慢垂下来。"}]}, {"id": "E05-S02.b04.o2", "label": "把接妹妹的后半句接回去", "sourceLine": 1163, "feedback": [{"id": "E05-S02.b04.o2.f1", "type": "line", "sourceLine": 1165, "speaker": "声画", "text": "林雨把光标往后拖。仓管员在录音里停了一下，说：“我妹放学没人接。”红色催办灯还亮着，一只陌生的手却把返单拖回本人收件箱。"}]}]},
    {"id": "E05-S02.b05", "sourceLine": 1167, "type": "line", "speaker": "林雨", "text": "你不是不肯做，你是在等人把话听完。"},
    {"id": "E05-S02.b06", "sourceLine": 1169, "type": "line", "speaker": "旁白", "text": "风停了一瞬。四件衣服的口袋同时翻开，四张纸各自朝不同的方向卷去。林雨跟着最先落下的那张，推开了楼顶尽头原本没有的铁门。"}
  ]},
  "E05-S03": {"id": "E05-S03", "chapter": "E05", "title": "四个收件窗", "next": "E05-S04", "time": "5月8日 深夜", "place": "楼顶与收件窗", "cue": "四次交件按物件确认；衣料落下给空间腾出路", "beats": [
    {"id": "E05-S03.b01", "sourceLine": 1176, "type": "line", "speaker": "旁白", "text": "铁门后是一排收件窗。每一扇玻璃里都有人等着，手里拿的不是人脸，是一件该交还的东西。"},
    {"id": "E05-S03.b02", "sourceLine": 1178, "type": "interaction", "kind": "retry", "prompt": "四个投递窗只有一个能给工资明细退回有日期的凭条。", "options": [{"id": "E05-S03.b02.o1", "label": "投到写着“优秀员工”的表扬栏", "sourceLine": 1180, "feedback": [{"id": "E05-S03.b02.o1.f1", "type": "line", "sourceLine": 1182, "speaker": "动作", "text": "纸被玻璃弹回来，折角多了一枚笑脸贴纸。雨衣继续滴水，数字没有被任何人登记。"}], "retry": true}, {"id": "E05-S03.b02.o2", "label": "打开申诉收件窗，留下工资单副本", "sourceLine": 1184, "feedback": [{"id": "E05-S03.b02.o2.f1", "type": "line", "sourceLine": 1186, "speaker": "声画", "text": "窗内的人把副本压进复写纸，日期戳落下。回执从小口递回来，柜面往后退了一格。"}]}]},
    {"id": "E05-S03.b03", "sourceLine": 1188, "type": "line", "speaker": "旁白", "text": "骑手的雨衣因此轻了一点。林雨把回执夹好，不替现实里的人去认领它。接着轮到那件卫衣：一只手按住辞职信的签名，又把笔推回去。"},
    {"id": "E05-S03.b04", "sourceLine": 1190, "type": "line", "speaker": "窗后声音", "text": "我改了三年才写到这句。别替我发，替我把前头那些废话删了。"},
    {"id": "E05-S03.b05", "sourceLine": 1192, "type": "line", "speaker": "旁白", "text": "林雨照做。保安的耳机里藏着邮费，衣袖自己在县名下面补上小组号；最后一扇窗里，妹妹把蛋糕放到两只纸碟中间，蓝蜡烛卡在盒绳里。"},
    {"id": "E05-S03.b06", "sourceLine": 1194, "type": "line", "speaker": "窗里的妹妹", "text": "她饿了就先让她吃。她要是五分钟也不歇，你别替她说没事。"},
    {"id": "E05-S03.b07", "sourceLine": 1196, "type": "line", "speaker": "旁白", "text": "林雨替她扶住歪掉的纸碟。玻璃上倒映出四张回执，也倒映出楼顶那根晾衣绳。她伸手去碰，旧衣夹夹住了指肚，疼得很实在。"}
  ]},
  "E05-S04": {"id": "E05-S04", "chapter": "E05", "title": "署名栏", "next": "E05-S05", "time": "5月9日 凌晨", "place": "楼顶与302", "cue": "阿岑能听金属夹响；现实群聊用手机画面", "beats": [
    {"id": "E05-S04.b01", "sourceLine": 1203, "type": "line", "speaker": "旁白", "text": "楼顶铁门在身后合上，风声也停了。林雨下到302门口时，周铭把新版本丢进了群里：缩略图里，郑家的门口接着厂里孩子的黑屏，片尾挂着她的名字。她没有进屋，先拨给阿岑。"},
    {"id": "E05-S04.b02", "sourceLine": 1205, "type": "line", "speaker": "阿岑", "text": "我也刚收到。门没锁，你进来；我把那一段停着。"},
    {"id": "E05-S04.b03", "sourceLine": 1207, "type": "line", "speaker": "林雨", "text": "我在门口。郑家的门、厂里的录音，不能这样接；我得看清他剪到哪儿了。"},
    {"id": "E05-S04.b04", "sourceLine": 1209, "type": "line", "speaker": "手机·周铭", "text": "客户等版本。撤了就只结你们做到现在的工时；成片的款，等下一个排期。"},
    {"id": "E05-S04.b05", "sourceLine": 1211, "type": "line", "speaker": "旁白", "text": "林雨推门进屋，把手机放在桌上，屏幕照着她的手。她看见那条被截掉的尾音，也看见署名栏正等她替谁担责。"},
    {"id": "E05-S04.b06", "sourceLine": 1213, "type": "interaction", "kind": "choice", "prompt": "留下哪一种处理记录？", "options": [{"id": "E05-S04.b06.o1", "label": "在项目群署名说明两处错接，拒交此版", "sourceLine": 1215, "feedback": [{"id": "E05-S04.b06.o1.f1", "type": "line", "sourceLine": 1217, "speaker": "手机·林雨", "text": "两个地点，两个人；我不同意这样接。署名林雨。仓管员只答应周三。"}, {"id": "E05-S04.b06.o1.f2", "type": "line", "sourceLine": 1219, "speaker": "阿岑", "text": "我也署名。饭你热着，电话我来打。"}]}, {"id": "E05-S04.b06.o2", "label": "撤回导出，私下把正确的整段交给阿岑", "sourceLine": 1221, "feedback": [{"id": "E05-S04.b06.o2.f1", "type": "line", "sourceLine": 1223, "speaker": "动作", "text": "林雨取消导出，把改正后的时间线传给阿岑。项目群的输入提示闪了一下，没有留下公开的拒剪记录。"}, {"id": "E05-S04.b06.o2.f2", "type": "line", "sourceLine": 1225, "speaker": "阿岑", "text": "文件我收着。以后有人拿我们的名字说事，至少咱俩知道那晚没答应过什么。"}]}]},
    {"id": "E05-S04.b07", "sourceLine": 1227, "when": "E05-S02.b04.o1", "type": "line", "speaker": "旁白", "text": "林雨把带时码的说明发给仓管员。对方回了“是周三”，过了半小时，又发来一张孩子画的周历；星期三被蓝笔圈得很大。"},
    {"id": "E05-S04.b08", "sourceLine": 1229, "when": "E05-S02.b04.o2", "type": "line", "speaker": "旁白", "text": "阿岑把那句“我妹放学没人接”剪成只给当事人的副本。对方回说，妹妹总以为姐姐在电视台上班，想先给她听。"},
    {"id": "E05-S04.b09", "sourceLine": 1231, "type": "line", "speaker": "旁白", "text": "门外的衣绳啪地掉下一根。老许抱着被单站在走廊，肩上夹着两只木夹。"},
    {"id": "E05-S04.b10", "sourceLine": 1233, "type": "line", "speaker": "老许", "text": "明早修水管要从阳台过，我上来收被单。看见你们灯亮，就多带了两杯豆浆；一甜一淡。"},
    {"id": "E05-S04.b11", "sourceLine": 1235, "type": "line", "speaker": "林雨", "text": "您还记得我喝哪杯？"},
    {"id": "E05-S04.b12", "sourceLine": 1237, "type": "line", "speaker": "老许", "text": "不记得。所以甜的留给我，省得猜。你们忙完把门带上，明早我再来敲。"}
  ]},
  "E05-S05": {"id": "E05-S05", "chapter": "E05", "title": "工钱", "next": "E06-S01", "time": "5月9日 早晨", "place": "三巷早摊", "cue": "拍摄暂停；电话里菜刀和砧板留完整一拍", "beats": [
    {"id": "E05-S05.b01", "sourceLine": 1244, "type": "line", "speaker": "旁白", "text": "林雨给妈妈打电话时，粉叔刚把第二笼肠粉揭开。电话那头先是菜刀碰砧板，妈妈才问她片子弄完没有。"},
    {"id": "E05-S05.b02", "sourceLine": 1246, "type": "line", "speaker": "林雨", "text": "那版我撤了。这月只能结几天工钱，给你的钱晚几天转。"},
    {"id": "E05-S05.b03", "sourceLine": 1248, "type": "line", "speaker": "妈妈", "text": "晚就晚。你姨欠我的麻将钱还没还，我先去堵她。她赢钱的时候，转账比谁快。"},
    {"id": "E05-S05.wages", "sourceLine": 1250, "pickup": "wages", "type": "line", "speaker": "旁白", "text": "阿岑把账本推给林雨看：已结的工时、还掉的镜头费、没有把握的尾款，各占一行。他把下一笔旁的镜头型号擦掉，纸上还留着铅笔压痕。"},
    {"id": "E05-S05.lens-later", "sourceLine": 1252, "pickup": "lens-later", "type": "line", "speaker": "阿岑", "text": "镜头先不买。月底房租我多接一场婚礼补；你别为了这张账把能睡的地方也让出去。"},
    {"id": "E05-S05.b04", "sourceLine": 1254, "type": "line", "speaker": "旁白", "text": "林雨挂电话时，粉叔把一碟肠粉往她面前推。小茵背着包从巷口过来，原本要上三楼借充电头，看见她们两个人只点了一碟，又把脚步放慢。"},
    {"id": "E05-S05.sister.1", "sourceLine": 1256, "pickup": "sister.1", "type": "line", "speaker": "旁白", "text": "林雨把筷子横在碟边，先问小茵：“你下班了？坐一会儿。这里有空位。”"},
    {"id": "E05-S05.sister.2", "sourceLine": 1258, "pickup": "sister.2", "type": "line", "speaker": "旁白", "text": "小茵没掏那部旧手机，只把包放到脚边：“我饿了。今天别问我开门那晚。”"},
    {"id": "E05-S05.sister.3", "sourceLine": 1260, "pickup": "sister.3", "type": "line", "speaker": "旁白", "text": "林雨把第二双筷子拆开，推到她手边：“不问。你吃完想上楼，就上楼；想在这儿坐，也行。”"},
    {"id": "E05-S05.b05", "sourceLine": 1262, "type": "line", "speaker": "旁白", "text": "三个人把一碟肠粉分干净。阿岑从账本里抬头，看见桌对面压着旧招租单：近厂、有窗、八百。窗下那道淡淡的印子，像水漫过又干了。到了二十二号，同一张照片被人发进《夜访》的群里：「有人住这附近吗？我交了押金，今晚过去，想找个人陪我看一眼。」", "pages": ["三个人把一碟肠粉分干净。阿岑从账本里抬头，看见桌对面压着旧招租单：近厂、有窗、八百。窗下那道淡淡的印子，像水漫过又干了。", "到了二十二号，同一张照片被人发进《夜访》的群里：「有人住这附近吗？我交了押金，今晚过去，想找个人陪我看一眼。」"]},
    {"id": "E05-S05.escort", "sourceLine": 1264, "pickup": "escort", "type": "line", "speaker": "林雨", "text": "我住前楼，可以在门口等你；看不看、住不住，还是你自己定。先把中介给你的房号发来，别把证件和电话发群里。"}
  ]},
  "E06-S01": {"id": "E06-S01", "chapter": "E06", "title": "墙里有人游泳", "next": "E06-S02", "time": "5月22日 傍晚", "place": "三巷十二号后楼", "cue": "雨季；同一扇窗分室外广告、室内高窗两个角度", "beats": [
    {"id": "E06-S01.b01", "sourceLine": 1275, "type": "line", "speaker": "旁白", "text": "林雨回了群里一句「我住前楼，下楼就到」。等她绕到十二号后面，门洞下已经站着一个拖箱子的青年，手机里是被裁得很亮的室内图；墙后传来一下一下的闷响，像有人在水里蹬墙。"},
    {"id": "E06-S01.meet-at-door", "sourceLine": 1277, "pickup": "meet-at-door", "type": "line", "speaker": "林雨", "text": "群里跟你说「下楼就到」的就是我。我住前楼。你给我看一下房号，别走错了。"},
    {"id": "E06-S01.night-bed", "sourceLine": 1279, "pickup": "night-bed", "type": "line", "speaker": "林雨", "text": "照片上那扇窗比这边的大。你跟中介说要了？"},
    {"id": "E06-S01.deposit", "sourceLine": 1281, "pickup": "deposit", "type": "line", "speaker": "新租客", "text": "给了八百。今晚不住进去，我得再住一晚旅馆。我想先看看窗，合不合适我自己说。"},
    {"id": "E06-S01.b02", "sourceLine": 1283, "type": "line", "speaker": "旁白", "text": "老许听见“窗”字，停在楼梯中间。他认出自己年轻时抬下去的隔板，也认出后来新闻照片里那道板缝。"},
    {"id": "E06-S01.b03", "sourceLine": 1285, "type": "line", "speaker": "老许", "text": "第一趟我只管抬。第二趟有人叫我留一条能搁电饭锅的边，我才知道里面摆了床。你要记，就两趟都记。"},
    {"id": "E06-S01.b04", "sourceLine": 1287, "type": "line", "speaker": "旁白", "text": "林雨没有马上拍他。罗叔去看后巷的门，阿岑沿楼梯找排水；林雨把青年手机里的图和眼前的房号并在一起，高窗下面那一大截墙被裁没了。"},
    {"id": "E06-S01.b05", "sourceLine": 1289, "type": "line", "speaker": "新租客", "text": "我妈给我装了两瓶炒辣椒。我答应给她拍灶台。中介只让我看插座，我也没敢多问。"}
  ]},
  "E06-S02": {"id": "E06-S02", "chapter": "E06", "title": "水线", "next": "E06-S03", "time": "5月22日 入夜", "place": "半地下层入口", "cue": "林雨视点是鱼缸；现实视点为旧隔板；响雷后镜头不闪白", "beats": [
    {"id": "E06-S02.water-entry", "sourceLine": 1296, "pickup": "water-entry", "type": "line", "speaker": "旁白", "text": "楼梯只拐一次弯。你先下去，把相机搁低，让林雨看见半层平台尽头那扇通后巷的栅门。青年在上面等箱子轮不响了，才跟下来。"},
    {"id": "E06-S02.water-first", "sourceLine": 1298, "pickup": "water-first", "type": "line", "speaker": "新租客", "text": "早知道在下面，我就不拖箱子来了。那玻璃后头是厨房？"},
    {"id": "E06-S02.water-answer", "sourceLine": 1300, "pickup": "water-answer", "type": "line", "speaker": "林雨", "text": "你在台阶上等我一下。我看见里面有人值班。"},
    {"id": "E06-S02.b01", "sourceLine": 1302, "type": "line", "speaker": "旁白", "text": "三号门本已封住，门里却站着提水桶的阿良。他隔着门朝一排看不见的人敲桶，像还在催谁往高处搬药。"},
    {"id": "E06-S02.b02", "sourceLine": 1304, "type": "line", "speaker": "阿良", "text": "柜顶搁药。水上得比人快。里面还有五张床没叫。"},
    {"id": "E06-S02.b03", "sourceLine": 1306, "type": "line", "speaker": "旁白", "text": "林雨往前一步，走道在她眼里变成玻璃鱼缸之间的窄缝。青年只看见天花板滴水，仍拖着箱子朝有灯的缓台走。"},
    {"id": "E06-S02.b04", "sourceLine": 1308, "type": "interaction", "kind": "retry", "prompt": "辨认往年洪水的痕迹。", "options": [{"id": "E06-S02.b04.o1", "label": "对齐正在晃动的亮边", "sourceLine": 1310, "feedback": [{"id": "E06-S02.b04.o1.f1", "type": "line", "sourceLine": 1312, "speaker": "动作", "text": "那条亮边跟着手电走。青年关掉手电，亮边没了，墙上的粗痕还在。"}], "retry": true}, {"id": "E06-S02.b04.o2", "label": "把床垫泥边和墙上沙粒连成一线", "sourceLine": 1314, "feedback": [{"id": "E06-S02.b04.o2.f1", "type": "line", "sourceLine": 1316, "speaker": "动作", "text": "两处干泥在同一高度。广告里的“采光窗”只比水线高一只手掌。"}]}]},
    {"id": "E06-S02.b05", "sourceLine": 1318, "type": "line", "speaker": "林雨", "text": "先别往里拖。这里进过水，今天也在返。"},
    {"id": "E06-S02.b06", "sourceLine": 1320, "type": "line", "speaker": "旁白", "text": "阿良看着她，手里水桶终于停了一下。"},
    {"id": "E06-S02.b07", "sourceLine": 1322, "type": "line", "speaker": "阿良", "text": "你听得见？以前他们一喊「阿良，借桶」，我隔三张床都听得见。现在换我喊了，这么近，谁都不应。"},
    {"id": "E06-S02.b08", "sourceLine": 1324, "type": "line", "speaker": "林雨", "text": "我先应外头这个。您让半步，别把他也困在里面。"}
  ]},
  "E06-S03": {"id": "E06-S03", "chapter": "E06", "title": "八百块", "next": "E06-S04", "time": "5月22日 夜", "place": "楼梯缓台", "cue": "真实出口被违规挂锁；有站在高处的接应人；无现实开锁教程", "beats": [
    {"id": "E06-S03.b01", "sourceLine": 1331, "type": "line", "speaker": "旁白", "text": "雨从雨棚底下反涌。通后巷的格栅被人从外头扣住。罗叔绕到后巷，老许上楼找业主要钥匙。阿岑先爬上缓台，放下相机，腾出两只手来。年轻人一手护着押金条，另一只手还没松开箱子。"},
    {"id": "E06-S03.b02", "sourceLine": 1333, "type": "line", "speaker": "新租客", "text": "你们叫我走，我今晚睡哪儿？八百退回来，也不是马上有地方住。"},
    {"id": "E06-S03.b03", "sourceLine": 1335, "type": "line", "speaker": "林雨", "text": "今晚先去许叔的201，有张能躺人的长凳。八百块我陪你去要。先把箱带给我，钱的事咱们上去再说。"},
    {"id": "E06-S03.b04", "sourceLine": 1337, "type": "line", "speaker": "旁白", "text": "林雨攥住箱带，另一端递给阿岑。隔着玻璃，花被子、袜子、折成四层的年画浮到了插座边。她愣了半拍。一个塑料盆从身后的架子上翻下来，砸在年轻人的鞋尖旁边。"},
    {"id": "E06-S03.b05", "sourceLine": 1339, "type": "interaction", "kind": "choice", "prompt": "先稳住谁？", "options": [{"id": "E06-S03.b05.o1", "label": "请新租客说出箱里带了什么", "sourceLine": 1341, "feedback": [{"id": "E06-S03.b05.o1.f1", "type": "line", "sourceLine": 1343, "speaker": "新租客", "text": "辣椒，两瓶！箱子别横着提，一横就漏。"}, {"id": "E06-S03.b05.o1.name", "type": "line", "sourceLine": 1345, "speaker": "新租客", "text": "我叫阿哲。上头有人接的时候喊我一声，我自己提。", "pickup": "name"}, {"id": "E06-S03.b05.o1.f2", "type": "line", "sourceLine": 1347, "speaker": "动作", "text": "阿岑照他说的把箱子竖着提上干台。青年自己把箱扣扣紧，空出一只手扶着林雨。"}]}, {"id": "E06-S03.b05.o2", "label": "请阿岑当面点答得到名字的人", "sourceLine": 1349, "feedback": [{"id": "E06-S03.b05.o2.f1", "type": "line", "sourceLine": 1351, "speaker": "阿岑", "text": "林雨？许叔？穿绿衣那个，你叫什么？"}, {"id": "E06-S03.b05.o2.f2", "type": "line", "sourceLine": 1353, "speaker": "新租客", "text": "阿哲。我妈的电话还没给你们，别替我往下念。"}]}]},
    {"id": "E06-S03.b06", "sourceLine": 1355, "type": "line", "speaker": "旁白", "text": "阿岑在干台上用脚抵住箱子。身后又有人敲桶。林雨转头，这回看清了：水里的手全指着同一扇门。"},
    {"id": "E06-S03.b07", "sourceLine": 1357, "type": "line", "speaker": "林雨", "text": "阿良，后门这道闩，当年也在外边？"},
    {"id": "E06-S03.b08", "sourceLine": 1359, "type": "line", "speaker": "旁白", "text": "阿良用桶沿磕了磕栏杆外壁。林雨贴着栅条往外叫：「罗叔，锁眼在你手边吗？」那边亮起一束手电，正照在锁上。"}
  ]},
  "E06-S04": {"id": "E06-S04", "chapter": "E06", "title": "从里面出去", "next": "E07-S01", "time": "5月22日 当夜", "place": "后巷格栅与201", "cue": "动作由四个人分担；无可搜集奖励置于危险区", "beats": [
    {"id": "E06-S04.b01", "sourceLine": 1366, "type": "line", "speaker": "旁白", "text": "罗叔在后巷举灯，钥匙从老许手里递到他手里。罗叔把钥匙转了半圈，铁栅开出一条缝，先照进来的是巷口的灯。箱子留在阿岑脚边的干台上。阿哲先从栅门缺口跨出去。他回身接林雨；她两脚踩到干砖，才回头看三号门。", "pages": ["罗叔在后巷举灯，钥匙从老许手里递到他手里。", "罗叔把钥匙转了半圈，铁栅开出一条缝，先照进来的是巷口的灯。", "箱子留在阿岑脚边的干台上。阿哲先从栅门缺口跨出去。", "他回身接林雨；她两脚踩到干砖，才回头看三号门。"]},
    {"id": "E06-S04.b02", "sourceLine": 1368, "type": "line", "speaker": "罗叔", "text": "旧锁环一直在我这面。那年最后是谁扣的，我没见；今天这一下，是外头扣的。"},
    {"id": "E06-S04.b03", "sourceLine": 1370, "type": "line", "speaker": "林雨", "text": "阿良，我在栏杆外。你要叫谁，我替你应一声。"},
    {"id": "E06-S04.b04", "sourceLine": 1372, "type": "line", "speaker": "阿良", "text": "花被子那床。……她搬佛山去了。我走到这儿才想起来。"},
    {"id": "E06-S04.b05", "sourceLine": 1374, "type": "line", "speaker": "林雨", "text": "那你先把桶放下。我在门外。"},
    {"id": "E06-S04.b06", "sourceLine": 1376, "type": "line", "speaker": "旁白", "text": "阿良放下桶，水面慢慢平了。阿岑把干毛巾扔来，罩住林雨的脸。转租人赶到时，先说自己收八百那天答应过，这道门能从里面开。", "pages": ["阿良放下桶，水面慢慢平了。", "阿岑把干毛巾扔来，罩住林雨的脸。转租人赶到时，先说自己收八百那天答应过，这道门能从里面开。"]},
    {"id": "E06-S04.dry-step", "sourceLine": 1378, "pickup": "dry-step", "type": "line", "speaker": "阿哲", "text": "刚才我怕你们劝我把箱子丢下，才不肯松手。现在台阶滑，你扶我一下；箱子我自己拿。"},
    {"id": "E06-S04.b07", "sourceLine": 1380, "type": "line", "speaker": "阿哲", "text": "我只亲眼见到今天是从外边扣的。你收钱那天怎么说的，跟今天不一样。"},
    {"id": "E06-S04.ownwords.1", "sourceLine": 1382, "pickup": "ownwords.1", "type": "line", "speaker": "旁白", "text": "那晚，阿哲和老许一道去追押金。回到201，林雨把样片放给老许看，画面停在老许比画隔板装在哪儿的那双手上。"},
    {"id": "E06-S04.ownwords.2", "sourceLine": 1384, "pickup": "ownwords.2", "type": "line", "speaker": "老许", "text": "后头我说知道里面摆了床，怎么没了？加回去。下一个来交钱的，才会问这门从里边开不开。"},
    {"id": "E06-S04.ownwords.3", "sourceLine": 1386, "pickup": "ownwords.3", "type": "line", "speaker": "林雨", "text": "我怕熟人认出您。您听听，我从第二趟开始接；您自己说到哪儿，咱们就留到哪儿。"},
    {"id": "E06-S04.b08", "sourceLine": 1388, "type": "line", "speaker": "旁白", "text": "阿哲把广告和押金条叠在一起：「明天我自己拿去说。」林雨把手机放回口袋。罗叔在旁边拿了支笔：「门怎么开的，我倒是能画给你。」"},
    {"id": "E06-S04.b09", "sourceLine": 1390, "type": "interaction", "kind": "choice", "prompt": "本人允许团队保留哪份可回查的实物记录？", "options": [{"id": "E06-S04.b09.o1", "label": "抄下仍在使用的柜台联系方式；阿哲保管广告原件", "sourceLine": 1392, "feedback": [{"id": "E06-S04.b09.o1.f1", "type": "line", "sourceLine": 1394, "speaker": "阿哲", "text": "锁环公开就够了。这个号我交材料用，你留一个能找回我的索引。"}]}, {"id": "E06-S04.b09.o2", "label": "请罗叔画出从哪面看得见锁环", "sourceLine": 1396, "feedback": [{"id": "E06-S04.b09.o2.f1", "type": "line", "sourceLine": 1398, "speaker": "罗叔", "text": "图上标入口方向。有人问当年谁扣锁，回来找我，我还是这句话。"}]}]},
    {"id": "E06-S04.b10", "sourceLine": 1400, "type": "set", "text": "出口朝向核对", "record": "grille", "scope": "public", "holder": "罗叔", "detail": "只公开本人确认的锁环朝向，不推定当年是谁扣锁。"},
    {"id": "E06-S04.contact", "type": "set", "record": "rental-contact", "text": "广告回查索引", "scope": "private", "holder": "阿哲", "detail": "原广告和押金条由阿哲保管。回查须联系本人，直播不可出示号码。", "when": "E06-S04.b09.o1", "origin": "permission"},
    {"id": "E06-S04.b11", "sourceLine": 1402, "type": "line", "speaker": "旁白", "text": "阿哲在201借插座充电，拍两瓶辣椒给妈妈看；照片里只有一张干桌子。他说等找到有灶的房再补拍。老许让他先留一瓶，月底来拿也行。临走，罗叔夹着那张门锁图托林雨办了件小事：「下回经过修鞋铺，替我看看老陈还开不开门。他膝盖又疼了。」"}
  ]},
  "E07-S01": {"id": "E07-S01", "chapter": "E07", "title": "只歇星期二", "next": "E07-S02", "time": "6月18日 下午", "place": "老生意街", "cue": "公告牌被取件条盖去一半；茶桌旁有两张不同的凳", "beats": [
    {"id": "E07-S01.b01", "sourceLine": 1413, "type": "line", "speaker": "旁白", "text": "林雨替罗叔跑了几趟修鞋铺，总碰上卷闸只开一半。这天下午她终于等到陈伯复诊回来。老人把营业牌翻成半天。黄姨借他半边柜台堆衣袋，罗叔周二要去女儿家带娃。三个人把各自的时间表一摊，才发现周二没有一处能让人把东西取齐。"},
    {"id": "E07-S01.return-favor", "sourceLine": 1415, "pickup": "return-favor", "type": "line", "speaker": "林雨", "text": "罗叔让我来看看陈伯还开不开门。我跑了几趟才知道，不是他不在，是三个人各自都抽不出同一段空。"},
    {"id": "E07-S01.b02", "sourceLine": 1417, "type": "line", "speaker": "陈伯", "text": "女儿说我一天挣的，不够打车看腿。昨儿我差点给人两只右脚。"},
    {"id": "E07-S01.b03", "sourceLine": 1419, "type": "line", "speaker": "阿岑", "text": "她给你算亏的，你偏往赚的算。"},
    {"id": "E07-S01.b04", "sourceLine": 1421, "type": "line", "speaker": "陈伯", "text": "先拿箱底左边那只。劝我之前，帮我把鞋找对。"},
    {"id": "E07-S01.tuesday.1", "sourceLine": 1423, "pickup": "tuesday.1", "type": "line", "speaker": "旁白", "text": "林雨把取件条压住：“周二下午，先算上我一个。”"},
    {"id": "E07-S01.tuesday.2", "sourceLine": 1425, "pickup": "tuesday.2", "type": "line", "speaker": "旁白", "text": "阿岑看她一眼：“七月以后你还住不住这儿？少接半天活，钱从哪儿出？咱们回去算，再跟陈伯定。”"},
    {"id": "E07-S01.b05", "sourceLine": 1427, "type": "line", "speaker": "旁白", "text": "一张“夜访街巷指引”在顾客手机里亮出来，把三家店标成灵异打卡点，还拿领取号编“生门”“死门”。短链来自星环试投，并非《夜访》发布。黄姨把那张截图扣到桌面。"},
    {"id": "E07-S01.b06", "sourceLine": 1429, "type": "line", "speaker": "黄姨", "text": "你问我怎么改袖子，我能讲一天。你拿这张问人住哪儿，我一句也不讲。"},
    {"id": "E07-S01.b07", "sourceLine": 1431, "type": "line", "speaker": "旁白", "text": "林雨记下公开链接和时间，先替陈伯把今天没人来取的三件东西送回各自的柜子。"}
  ]},
  "E07-S02": {"id": "E07-S02", "chapter": "E07", "title": "左脚走过的路", "next": "E07-S03", "time": "6月18日 黄昏", "place": "修鞋档", "cue": "老电视反光延伸街面；硬币声和鞋钉声有别", "beats": [
    {"id": "E07-S02.b01", "sourceLine": 1438, "type": "line", "speaker": "旁白", "text": "一双一大一小的旧帆布鞋放在档口外。林雨提起鞋袋，街面忽然拉长，三个拎工具袋的人各走各的，前头那个人左脚不敢落地。阿岑只听见一轻一重的钉声，指了指鞋跟。"},
    {"id": "E07-S02.b02", "sourceLine": 1440, "type": "line", "speaker": "陈伯", "text": "他左脚躲着踩。上回鞋底有根钉，我欠他一片垫子。让他坐，别叫他再走一遍。"},
    {"id": "E07-S02.b03", "sourceLine": 1442, "type": "interaction", "kind": "inspect", "prompt": "查哪处补痕能找到主人？", "options": [{"id": "E07-S02.b03.o1", "label": "翻看左鞋垫内侧半寸厚的补片", "sourceLine": 1444, "feedback": [{"id": "E07-S02.b03.o1.f1", "type": "line", "sourceLine": 1446, "speaker": "动作", "text": "厚垫避开旧钉伤。走得最慢的人回头，脱鞋试了两步，终于坐下。"}]}, {"id": "E07-S02.b03.o2", "label": "对柜上重复使用的袋号与旧鞋底的铅笔字", "sourceLine": 1448, "feedback": [{"id": "E07-S02.b03.o2.f1", "type": "line", "sourceLine": 1450, "speaker": "动作", "text": "四十三号袋换过绳，鞋底的三角点还在。陈伯把袋递给最后一位客人，给他的脚跟让开地方。"}]}]},
    {"id": "E07-S02.b04", "sourceLine": 1452, "type": "line", "speaker": "旁白", "text": "真正等取鞋的骑手在柜台边试穿，没人把旧人的事塞给他。阿岑替陈伯把歪凳垫平，林雨把空鞋袋挂回原处。"}
  ]},
  "E07-S03": {"id": "E07-S03", "chapter": "E07", "title": "把原来的边留着", "next": "E07-S04", "time": "6月18日 夜", "place": "黄姨改衣铺", "cue": "裁衣镜与现实试衣镜有不同边框；撤回镜面拍摄", "beats": [
    {"id": "E07-S03.b01", "sourceLine": 1459, "type": "line", "speaker": "旁白", "text": "姑娘想把牛仔裤改短，又舍不得裤脚那圈旧边。黄姨让她坐下、站起，摸到膝弯，才在靠上一截画粉线。"},
    {"id": "E07-S03.b02", "sourceLine": 1461, "type": "line", "speaker": "黄姨", "text": "原边留着，从上头收。你穿着，我才知道该收多少。"},
    {"id": "E07-S03.b03", "sourceLine": 1463, "type": "line", "speaker": "旁白", "text": "镜里，林雨身上叠着几件不合身的衣服，领口垂着“懂事”“肯熬夜”的旧标签。她摸到最底下的摄影证。"},
    {"id": "E07-S03.b04", "sourceLine": 1465, "type": "line", "speaker": "林雨", "text": "这里能拆牌子吗？"},
    {"id": "E07-S03.b05", "sourceLine": 1467, "type": "line", "speaker": "黄姨", "text": "你挑哪一道。扎肉就放松一寸，别等人来取衣服才知道剪错。"},
    {"id": "E07-S03.b06", "sourceLine": 1469, "type": "interaction", "kind": "choice", "prompt": "选择保留衣服的哪一处。", "options": [{"id": "E07-S03.b06.o1", "label": "从内侧拆掉扎颈那针，保留旧布", "sourceLine": 1471, "feedback": [{"id": "E07-S03.b06.o1.f1", "type": "line", "sourceLine": 1473, "speaker": "动作", "text": "整排标签滑出。林雨把母亲寄来的洗衣票单独留下，抻直领口。"}]}, {"id": "E07-S03.b06.o2", "label": "给自己的衣服补出一个能放公交卡的兜", "sourceLine": 1475, "feedback": [{"id": "E07-S03.b06.o2.f1", "type": "line", "sourceLine": 1477, "speaker": "动作", "text": "工牌缩回线缝，新口袋里公交卡沉到底。林雨抬手够到门边。"}]}]},
    {"id": "E07-S03.b07", "sourceLine": 1479, "type": "line", "speaker": "旁白", "text": "姑娘先同意拍“旧牛仔裤改短”的局部照，走到门口又想起母亲会认得那朵补花。林雨当面删照，归还签名页。"},
    {"id": "E07-S03.b08", "sourceLine": 1481, "type": "line", "speaker": "姑娘", "text": "我明天还是原来时间取？"},
    {"id": "E07-S03.phone-down", "sourceLine": 1483, "pickup": "phone-down", "type": "line", "speaker": "林雨", "text": "明天你只管来取裤子。手机我收了。"},
    {"id": "E07-S03.b09", "sourceLine": 1485, "type": "line", "speaker": "黄姨", "text": "押金在我这儿，不在电视台。线走完才取，早来也没用。"},
    {"id": "E07-S03.b10", "sourceLine": 1487, "type": "set", "text": "衣物图像授权已撤回", "record": "garment", "scope": "withdrawn", "holder": "姑娘本人", "detail": "局部照已当面删除，授权页交回本人。节目索引只留取回状态。"}
  ]},
  "E07-S04": {"id": "E07-S04", "chapter": "E07", "title": "无齿的钥匙", "next": "E07-S05", "time": "6月19日 傍晚", "place": "钥匙档", "cue": "三柜三钥；放错可原处重来；无齿坯单独建图", "beats": [
    {"id": "E07-S04.b01", "sourceLine": 1494, "type": "line", "speaker": "旁白", "text": "有人拿着网上存下的门牌照要配钥匙，罗叔照登记本打给本人确认。来人走后，真正的店主也拿着同一张照片来；罗叔还是让他等回电。"},
    {"id": "E07-S04.b02", "sourceLine": 1496, "type": "line", "speaker": "林雨", "text": "熟人也等？"},
    {"id": "E07-S04.b03", "sourceLine": 1498, "type": "line", "speaker": "罗叔", "text": "越熟，越该等得起。你看着水壶，我打一通。"},
    {"id": "E07-S04.b04", "sourceLine": 1500, "type": "line", "speaker": "旁白", "text": "他排开三个匣子：鞋袋归陈伯，衣袋归黄姨，领用页归自己。郑家钥匙的铜屑和后楼格栅的齿印还在板缝里，像三扇旧门都在等原主。"},
    {"id": "E07-S04.b05", "sourceLine": 1502, "type": "interaction", "kind": "retry", "prompt": "三家营业时间错开，网上发哪份指引？", "options": [{"id": "E07-S04.b05.o1", "label": "用付修人住址对照袋号，标谁家门近", "sourceLine": 1504, "feedback": [{"id": "E07-S04.b05.o1.f1", "type": "line", "sourceLine": 1506, "speaker": "黄姨", "text": "我收裤脚长短，不收住址。重写，只写来哪家柜台。"}], "retry": true}, {"id": "E07-S04.b05.o2", "label": "按取件号找柜台，写明周二暂存和本人核验", "sourceLine": 1508, "feedback": [{"id": "E07-S04.b05.o2.f1", "type": "line", "sourceLine": 1510, "speaker": "动作", "text": "三家各收一份。粉叔桌上只贴营业时间，真正的号码收进柜台。"}]}]},
    {"id": "E07-S04.b06", "sourceLine": 1512, "type": "line", "speaker": "旁白", "text": "罗叔拿出一片无齿坯：旧柜档能借，签了值班约定才配齿；没人照看，它仍旧挂锁。"},
    {"id": "E07-S04.b07", "sourceLine": 1514, "type": "interaction", "kind": "choice", "prompt": "谁来保管将来的柜档钥匙坯？", "options": [{"id": "E07-S04.b07.o1", "label": "收下无齿坯，答应先试排一个值班月", "sourceLine": 1516, "feedback": [{"id": "E07-S04.b07.o1.f1", "type": "line", "sourceLine": 1518, "speaker": "林雨", "text": "给我。我先算车钱。排不出来，我当面还。"}, {"id": "E07-S04.b07.o1.f2", "type": "line", "sourceLine": 1520, "speaker": "罗叔", "text": "没齿，拧坏了别赖我。"}]}, {"id": "E07-S04.b07.o2", "label": "交回罗叔，她只把取件办法写完整", "sourceLine": 1522, "feedback": [{"id": "E07-S04.b07.o2.f1", "type": "line", "sourceLine": 1524, "speaker": "林雨", "text": "下个月住哪儿我还不知道。先留你木板上，等能值班的人来拿。"}, {"id": "E07-S04.b07.o2.f2", "type": "line", "sourceLine": 1526, "speaker": "罗叔", "text": "行。帮我把挂绳穿回去。"}]}]},
    {"id": "E07-S04.b07.o1.key", "type": "set", "text": "试排值班月的无齿坯", "record": "cabinet-key", "scope": "private", "holder": "林雨", "detail": "本人先保管，待排定值班、签约后配齿。", "when": "E07-S04.b07.o1", "origin": "permission"},
    {"id": "E07-S04.b07.o2.key", "type": "set", "text": "柜档钥匙坯已交回", "record": "cabinet-key", "scope": "returned", "holder": "罗叔", "detail": "钥匙坯留在罗叔的木板上，林雨只整理取件办法。", "when": "E07-S04.b07.o2", "origin": "permission"},
    {"id": "E07-S04.b08", "sourceLine": 1528, "type": "line", "speaker": "旁白", "text": "沈嘉查到试投邮件：星环曾向她本人要排期，图上出镜人写着林雨。林雨认出“生门”底图，是自己早年挂上去的雨巷一帧。"},
    {"id": "E07-S04.b09", "sourceLine": 1530, "type": "set", "text": "短链试投的时间与署名", "record": "campaign", "scope": "public", "holder": "夜访／沈嘉", "detail": "公开只用已经发布的截图说明日期和署名；沈嘉收到的邮件仅供私下核对。"}
  ]},
  "E07-S05": {"id": "E07-S05", "chapter": "E07", "title": "谁来点灯", "next": "E08-S01", "time": "6月20日至7月初", "place": "粉摊与剪辑桌", "cue": "三铺照常营业；手机群里的转发音从密到稀", "beats": [
    {"id": "E07-S05.b01", "sourceLine": 1537, "type": "line", "speaker": "旁白", "text": "周铭撤下了那张把三家店写成打卡点的短链，仍把“7月18日·今宵剧场”留在林雨的日历上。合同和自播预算摊在同一张桌上，谁也没收走。"},
    {"id": "E07-S05.terms", "sourceLine": 1539, "pickup": "terms", "type": "line", "speaker": "手机·周铭", "text": "签约有首页和保底，片子交我排；不签你们自己播，带宽和器材自己扛。到十八号上午给我一句准话。"},
    {"id": "E07-S05.b02", "sourceLine": 1541, "type": "line", "speaker": "阿岑", "text": "我想要固定做自己的片，也想不用每月借镜头。可最后那一下，得咱俩自己按。"},
    {"id": "E07-S05.b03", "sourceLine": 1543, "type": "line", "speaker": "林雨", "text": "我先听小茵肯给哪一截。"},
    {"id": "E07-S05.audience.1", "sourceLine": 1545, "pickup": "audience.1", "type": "line", "speaker": "小茵", "text": "原先骂过琴姐的那些人，我也想让他们听一回。镜头朝哪儿，我自己挑。"},
    {"id": "E07-S05.own-cut", "sourceLine": 1547, "pickup": "own-cut", "type": "line", "speaker": "小茵", "text": "我拖到门轴响才停。有人催也不往后放；要骂，就让他骂我开过门。"},
    {"id": "E07-S05.b04", "sourceLine": 1549, "type": "line", "speaker": "粉叔", "text": "今宵以前是露天戏的叫法。棚能借，锅不能占。"},
    {"id": "E07-S05.ask-note", "sourceLine": 1551, "pickup": "ask-note", "when": "E05-S04.b06.o2", "type": "line", "speaker": "阿岑", "text": "她同意两句时码给柜档看。妹妹叫什么、在哪儿接，都不写。"},
    {"id": "E07-S05.note", "sourceLine": 1553, "pickup": "note", "when": "E05-S04.b06.o2", "type": "interaction", "kind": "choice", "prompt": "五月那份撤回记录只在两人手机里。现在怎样处理？", "options": [{"id": "E07-S05.note.o1", "label": "把去名的处理说明签给柜档查阅", "sourceLine": 1555, "feedback": [{"id": "E07-S05.note.o1.f1", "type": "line", "sourceLine": 1557, "speaker": "林雨", "text": "两刀都是我撤的。今天的日期也签上；谁问这张纸，就找我。"}]}, {"id": "E07-S05.note.o2", "label": "只保存原来的私下记录", "sourceLine": 1559, "feedback": [{"id": "E07-S05.note.o2.f1", "type": "line", "sourceLine": 1561, "speaker": "林雨", "text": "当时是私下交的，就这样留着。她肯给我看，已经帮了很大忙。"}]}]},
    {"id": "E07-S05.right-to-cut", "sourceLine": 1563, "pickup": "right-to-cut", "type": "line", "speaker": "小茵", "text": "我说开门那晚，原来那些人能听见？他们单剪卷闸，你管得住吗？"},
    {"id": "E07-S05.answer-her", "sourceLine": 1565, "pickup": "answer-her", "type": "line", "speaker": "林雨", "text": "你说的那一段，哪一路都由你自己播。签给他们，明天片头怎么剪，我撤不了。"},
    {"id": "E07-S05.b05", "sourceLine": 1567, "type": "line", "speaker": "旁白", "text": "林雨把“18日，自己号”写到日历上，推给小茵。小茵在门轴响的那一格画了条线。林雨再把302续到27日，把水杯往里挪一寸；旧电视只映出一张空凳。"}
  ]},
  "E08-S01": {"id": "E08-S01", "chapter": "E08", "title": "场租和晚饭", "next": "E08-S02", "time": "7月18日 17:40", "place": "粉摊临时播出台", "cue": "旧屏只接预监；主频道在团队手机；分轨供字幕", "beats": [
    {"id": "E08-S01.b01", "sourceLine": 1578, "type": "line", "speaker": "旁白", "text": "阿岑把延长线贴到桌腿内侧，给婴儿车留出过道。周铭提两盒饭来，合同压在饭盒上：保底月费、器材预支、再剪权限，写得很整齐。"},
    {"id": "E08-S01.b02", "sourceLine": 1580, "type": "line", "speaker": "周铭", "text": "签了，首页推你们；不签，号归你们，带宽我不买。饭照吃，选择也照写。"},
    {"id": "E08-S01.b03", "sourceLine": 1582, "type": "line", "speaker": "旁白", "text": "林雨把公开试投和未签授权单并排。她指出“附近住户推荐”的时间，周铭承认那晚广告价问得多，第二天才叫人撤。"},
    {"id": "E08-S01.b04", "sourceLine": 1584, "when": "E05-S04.b06.o1", "type": "line", "speaker": "手机·沈嘉", "text": "五月那条群里署名还在。试投前，你已经写过哪些镜头不能错接。"},
    {"id": "E08-S01.b05", "sourceLine": 1586, "when": "E05-S04.b06.o2", "type": "line", "speaker": "阿岑", "text": "五月私聊我备份了。能说明咱俩同意过什么，对外却看不出我们怎么回。"},
    {"id": "E08-S01.b06", "sourceLine": 1588, "type": "line", "speaker": "旁白", "text": "林雨把最终发送按钮旁的手机递给小茵，先让她确认桌面会拍到哪里。"},
    {"id": "E08-S01.stop-button", "sourceLine": 1590, "pickup": "stop-button", "type": "line", "speaker": "林雨", "text": "第一段从你的原片开始，也到你按停为止。上次是我替你把七秒以后写完；今晚每一次播放，你自己说停。"}
  ]},
  "E08-S02": {"id": "E08-S02", "chapter": "E08", "title": "见得到的人", "next": "E08-S03", "time": "7月18日 入夜", "place": "三巷与粉摊", "cue": "红伞鬼身仅林雨层；观众只能看物理事件、获许可的活人声", "beats": [
    {"id": "E08-S02.b01", "sourceLine": 1597, "type": "line", "speaker": "旁白", "text": "有人举手机等红伞。阿琴把粉叔夹板上的电话遮住，阿岑扶正挡路的折凳。阿哲来拿留在201的辣椒，瓶盖上还贴着老许写的“有人回来拿”。"},
    {"id": "E08-S02.b02", "sourceLine": 1599, "type": "line", "speaker": "阿哲", "text": "我换工了，我妈才知道那屋什么样。今天别把手机转我这边。"},
    {"id": "E08-S02.b03", "sourceLine": 1601, "type": "line", "speaker": "林雨", "text": "拍桌就够。你从我身后过去。"},
    {"id": "E08-S02.b04", "sourceLine": 1603, "when": "E04-S02.b03.o1", "type": "line", "speaker": "旁白", "text": "粉叔把旧回单压进电话簿。家属还在比笔迹，桌上只有“待核”，直播不替她填名字。"},
    {"id": "E08-S02.b05", "sourceLine": 1605, "when": "E04-S02.b03.o2", "type": "line", "speaker": "旁白", "text": "饭缸轮廓夹在账页背面，粉叔盖住可能映出屋号的折角。"},
    {"id": "E08-S02.b06", "sourceLine": 1607, "type": "line", "speaker": "旁白", "text": "牌响第一声。林雨看见等灯的人各自坐好，有人撑伞，有人端空碗；阿岑只听见不同重量的椅脚响，屏幕里一排椅子仍是空的。"},
    {"id": "E08-S02.b07", "sourceLine": 1609, "when": "E03-S05.b07.o1", "type": "line", "speaker": "旁白", "text": "梁安把四枚硬币无声排到桌子靠他那边。林雨把过弯的杯子挪到反方向。"},
    {"id": "E08-S02.b08", "sourceLine": 1611, "when": "E03-S05.b07.o2", "type": "line", "speaker": "声画", "text": "空桌沿响四下。阿岑抬头，朝空椅扬了扬下巴。"},
    {"id": "E08-S02.b09", "sourceLine": 1613, "type": "line", "speaker": "小梅", "text": "他今天吃过了。别拍我爸吃饭，我就来看看你最后播什么。"},
    {"id": "E08-S02.b10", "sourceLine": 1615, "type": "line", "speaker": "林雨", "text": "坐边上？人来人往会挤。"},
    {"id": "E08-S02.b11", "sourceLine": 1617, "type": "line", "speaker": "小梅", "text": "边上就好。走的时候不用人让路。"}
  ]},
  "E08-S03": {"id": "E08-S03", "chapter": "E08", "title": "今晚用哪一路", "next": null, "time": "7月18日 20:55", "place": "频道控制桌", "cue": "选项前可回看两份方案与财务约定；锁定条件显示原因", "beats": [
    {"id": "E08-S03.b01", "sourceLine": 1624, "type": "line", "speaker": "旁白", "text": "周铭的审定片只用《夜访》自己的空巷、柜门和红灯，却把窄门关上的画面放在“女孩求助”后，掐掉开门声，片尾问“你敢来吗”。阿岑看着那一帧，先开口。"},
    {"id": "E08-S03.b02", "sourceLine": 1626, "type": "line", "speaker": "阿岑", "text": "门是我举机子拍的，我记得它开着。要签，把我列掌镜；有人问我，我还是这么说。"},
    {"id": "E08-S03.b03", "sourceLine": 1628, "type": "line", "speaker": "林雨", "text": "自播呢？"},
    {"id": "E08-S03.b04", "sourceLine": 1630, "type": "line", "speaker": "阿岑", "text": "我守线。你忘词就喝口水，我给你留着。下个月镜头还得借。"},
    {"id": "E08-S03.b05", "sourceLine": 1632, "type": "interaction", "kind": "branch", "prompt": "玩家决定节目怎样上屏。", "options": [{"id": "E08-S03.b05.o1", "label": "签下星环独家合作，交付审定片", "sourceLine": 1634, "feedback": [{"id": "E08-S03.b05.o1.f1", "type": "line", "sourceLine": 1636, "speaker": "动作", "text": "两人签下权利栏。阿岑在附页记下不同意的剪口；林雨以发布人身份按下交付。"}], "to": "E08-S08"}, {"id": "E08-S03.b05.o2", "label": "用《夜访》自己的号开证人桌，放弃独家保底", "sourceLine": 1638, "feedback": [{"id": "E08-S03.b05.o2.f1", "type": "line", "sourceLine": 1640, "speaker": "动作", "text": "周铭收起合同，留下两盒饭。林雨铺平白纸，把手机交给小茵先核对画面。"}], "to": "E08-S04"}]}
  ]},
  "E08-S04": {"id": "E08-S04", "chapter": "E08", "title": "给愿意开口的人", "next": "E08-S05", "time": "7月18日 21:00", "place": "证人桌", "cue": "证物来源和用途核对；首次公众公开仅使用批准片段", "beats": [
    {"id": "E08-S04.b01", "sourceLine": 1647, "type": "line", "speaker": "小茵", "text": "我不露脸。七秒你们记得，开门以后那句还是我妈的事。"},
    {"id": "E08-S04.correction.1", "sourceLine": 1649, "pickup": "correction.1", "type": "line", "speaker": "小茵", "text": "门是我开的。那一晚我就在对街。"},
    {"id": "E08-S04.b02", "sourceLine": 1651, "type": "line", "speaker": "林雨", "text": "到门轴响就停。你点，我不替你按。"},
    {"id": "E08-S04.b03", "sourceLine": 1653, "type": "interaction", "kind": "choice", "prompt": "在更正之后，完整交代哪一项？", "options": [{"id": "E08-S04.b03.o1", "label": "播开门声和同机位的遮挡", "sourceLine": 1655, "feedback": [{"id": "E08-S04.b03.o1.f1", "type": "line", "sourceLine": 1657, "speaker": "声画", "text": "小茵亲手点播放，屏幕标出原片止处。林雨从镜头前往右移一步，阿琴将门推开；观众看清这一步有多远。"}, {"id": "E08-S04.b03.o1.f2", "type": "line", "sourceLine": 1659, "speaker": "阿琴", "text": "今天我推，那天她推。水买不买？不买我关冰柜。"}]}, {"id": "E08-S04.b03.o2", "label": "播老邓的亲历，把采访原带留给朋友", "sourceLine": 1661, "feedback": [{"id": "E08-S04.b03.o2.correction", "type": "line", "sourceLine": 1663, "speaker": "声画", "text": "先放开门那一声。音轨到门轴响就停住，小茵收起手机，把桌面让给老邓。", "pickup": "correction"}, {"id": "E08-S04.b03.o2.f1", "type": "line", "sourceLine": 1665, "speaker": "老邓", "text": "电脑开四十二分钟，人等到两点。给孩子打多久游戏算账，别把两样加一块。"}, {"id": "E08-S04.b03.o2.f2", "type": "line", "sourceLine": 1667, "speaker": "动作", "text": "旧采访没有上传。朋友留存的语音里杯子倒了，过弯自己去拿抹布。"}]}, {"id": "E08-S04.b03.o3", "label": "请罗叔在桌上比旧格栅内外", "sourceLine": 1669, "feedback": [{"id": "E08-S04.b03.o3.correction", "type": "line", "sourceLine": 1671, "speaker": "声画", "text": "先放开门那一声。音轨到门轴响就停住，小茵收起手机，把桌面让给罗叔。", "pickup": "correction"}, {"id": "E08-S04.b03.o3.f1", "type": "line", "sourceLine": 1673, "speaker": "罗叔", "text": "我只能指出哪头在里面。那年我到时锁已挂着，挂的人我没看见；今天这个朝向你能画。"}, {"id": "E08-S04.b03.o3.f2", "type": "line", "sourceLine": 1675, "speaker": "动作", "text": "公开画面只有手和纸上的格栅。阿哲的姓名、住处和联系号留在本人手机里。"}]}]},
    {"id": "E08-S04.b04", "sourceLine": 1677, "type": "line", "speaker": "旁白", "text": "林雨念出试投日期：“那天我没签字。巷口那张底图，是我先挂上去的。”"},
    {"id": "E08-S04.b05", "sourceLine": 1679, "when": "E06-S04.b09.o1", "type": "line", "speaker": "阿哲", "text": "原广告在我这儿。有人问日期，你把话带给我，我自己回。"},
    {"id": "E08-S04.b06", "sourceLine": 1681, "when": "E06-S04.b09.o2", "type": "line", "speaker": "罗叔", "text": "先看方向图。你照着画一遍，就知道屋里哪边够不着。"},
    {"id": "E08-S04.b07", "sourceLine": 1683, "when": "E07-S04.b07.o1", "type": "line", "speaker": "动作", "text": "无齿坯贴在林雨裤袋上，冷了一晚，现在终于有点温度。"},
    {"id": "E08-S04.b08", "sourceLine": 1685, "type": "line", "speaker": "旁白", "text": "第二声牌响。林雨看见梁安挤进大人间看弹幕。"},
    {"id": "E08-S04.b09", "sourceLine": 1687, "type": "line", "speaker": "梁安", "text": "他们谁知道我叫什么？"},
    {"id": "E08-S04.b10", "sourceLine": 1689, "type": "line", "speaker": "林雨", "text": "你愿意告诉他们吗？"},
    {"id": "E08-S04.b11", "sourceLine": 1691, "type": "line", "speaker": "梁安", "text": "不了。我队里的人知道就行。"}
  ]},
  "E08-S05": {"id": "E08-S05", "chapter": "E08", "title": "播完以后", "next": null, "time": "7月18日 收播后", "place": "粉摊外", "cue": "自然租约到期；街铺按原营业表开门", "beats": [
    {"id": "E08-S05.b01", "sourceLine": 1698, "type": "line", "speaker": "旁白", "text": "第三声来得很迟。节目已经关了，阿琴在屋里喊“里面还有灯”，粉叔给过饭点的人蒸第二轮。九天后，老许捏着302的钥匙回执，站在粉摊桌边。", "pages": ["第三声来得很迟。节目已经关了，阿琴在屋里喊“里面还有灯”，粉叔给过饭点的人蒸第二轮。", "九天后，老许捏着302的钥匙回执，站在粉摊桌边。"]},
    {"id": "E08-S05.lease-count", "sourceLine": 1700, "pickup": "lease-count", "type": "line", "speaker": "老许", "text": "二十七号到期。你续不续？不续我好把水电算给你，床底那块砖别又让它跑。"},
    {"id": "E08-S05.cabinet-hours", "sourceLine": 1702, "pickup": "cabinet-hours", "type": "line", "speaker": "罗叔", "text": "旧柜档能借，不是白替你看。周二下午两点到五点，你到了我才开锁。"},
    {"id": "E08-S05.b02", "sourceLine": 1704, "type": "line", "speaker": "陈伯", "text": "四个周二，两点到五点。少得了一天，提早说；临时有活出城，别让人白等。"},
    {"id": "E08-S05.b03", "sourceLine": 1706, "when": "E05-S04.b06.o1", "type": "line", "speaker": "旁白", "text": "林雨给陈伯看那两行署名说明。他把查阅办法写到排班纸背面，再把笔还给她。"},
    {"id": "E08-S05.signed-later", "sourceLine": 1708, "pickup": "signed-later", "when": "E07-S05.note.o1", "type": "line", "speaker": "罗叔", "text": "六月补签那张夹进去了。谁问怎么剪的，我给他看纸，名字给你的。"},
    {"id": "E08-S05.b04", "sourceLine": 1710, "when": "E07-S04.b07.o1", "type": "line", "speaker": "旁白", "text": "罗叔等她把钥匙坯搁下，没有替她决定要不要配齿。"},
    {"id": "E08-S05.b05", "sourceLine": 1712, "type": "interaction", "kind": "branch", "prompt": "选择这个夏天以后怎样过日子。", "options": [{"id": "E08-S05.b05.o1", "label": "还302钥匙，与街坊逐家交回查阅副本", "sourceLine": 1714, "feedback": [{"id": "E08-S05.b05.o1.f1", "type": "line", "sourceLine": 1716, "speaker": "动作", "text": "林雨折好转交清单，收起用了四个月的水杯。"}], "to": "E08-S06"}, {"id": "E08-S05.b05.o2", "label": "认领每周二的旧柜档，开一盏查阅灯", "sourceLine": 1718, "feedback": [{"id": "E08-S05.b05.o2.f1", "type": "line", "sourceLine": 1720, "speaker": "动作", "text": "林雨在值班纸上签下四个周二。罗叔去取能开柜的钥匙。"}], "to": "E08-S07", "requires": ["E05-S04.b06.o1", "E07-S04.b07.o1"], "lockReason": "须有署名处理说明和四周值班的无齿坯", "alternatives": {"E05-S04.b06.o1": ["E07-S05.note.o1"]}}]}
  ]},
  "E08-S06": {"id": "E08-S06", "chapter": "E08", "title": "结局一　离开", "next": null, "time": "8月 初", "place": "棠西公交站", "cue": "车内外两层声场", "beats": [
    {"id": "E08-S06.handover.1", "sourceLine": 1727, "pickup": "handover.1", "type": "line", "speaker": "旁白", "text": "转交清单已经勾完。林雨把它折进票夹，最后看了一眼302的钥匙回执。"},
    {"id": "E08-S06.handover.2", "sourceLine": 1729, "pickup": "handover.2", "type": "line", "speaker": "林雨", "text": "我接了外地的活。周二我守不了，柜档别替我留人。"},
    {"id": "E08-S06.handover.3", "sourceLine": 1731, "pickup": "handover.3", "type": "line", "speaker": "旁白", "text": "小茵接过林雨装票据的布袋，挂到行李把上。两个人沿水沟走到公交站，谁也没有催谁。"},
    {"id": "E08-S06.return.lease", "type": "set", "text": "302钥匙已还", "record": "lease", "scope": "returned", "holder": "老许", "detail": "由原持有人保管，团队只留交还记录。", "origin": "permission"},
    {"id": "E08-S06.return.zheng", "type": "set", "text": "郑家查阅副本已交回", "record": "zheng", "scope": "returned", "holder": "郑家", "detail": "由原持有人保管，团队只留交还记录。", "origin": "permission"},
    {"id": "E08-S06.return.orders", "type": "set", "text": "回单查阅副本已交回", "record": "orders", "scope": "returned", "holder": "粉叔", "detail": "由原持有人保管，团队只留交还记录。", "origin": "permission"},
    {"id": "E08-S06.return.blank", "type": "set", "text": "柜档钥匙坯已交回", "record": "cabinet-key", "scope": "returned", "holder": "罗叔", "detail": "每周二的试排结束，未配齿的钥匙坯交回柜档。", "when": "E07-S04.b07.o1", "origin": "permission"},
    {"id": "E08-S06.b01", "sourceLine": 1733, "type": "line", "speaker": "旁白", "text": "老许已经把押金和水电结清。小茵来还短充电线，阿琴把一碟肠粉递到车窗下。"},
    {"id": "E08-S06.b02", "sourceLine": 1735, "type": "line", "speaker": "阿琴", "text": "这碟不收你钱，留账上下次收。你不回来，我追到网上要。"},
    {"id": "E08-S06.b03", "sourceLine": 1737, "type": "line", "speaker": "林雨", "text": "记我一碟。我怕下次回来，粉涨价了。"},
    {"id": "E08-S06.b04", "sourceLine": 1739, "type": "line", "speaker": "旁白", "text": "车窗被敲三下。阿岑回头只见雨棚边甩来湿伞；林雨看见张婆婆转身，在路口给下一班夜车留位。几周后有人找旧票上的店，她按约先问店主，再回拨，没有替谁接下下一场采访。", "pages": ["车窗被敲三下。阿岑回头只见雨棚边甩来湿伞；林雨看见张婆婆转身，在路口给下一班夜车留位。", "几周后有人找旧票上的店，她按约先问店主，再回拨，没有替谁接下下一场采访。"]},
    {"id": "E08-S06.b05", "sourceLine": 1741, "type": "line", "speaker": "片尾", "text": "离开。八月的通讯录里，“粉叔”下面多了一行：“右耳听不大清”。"},
    {"id": "E08-S06.b06", "sourceLine": 1743, "type": "end", "text": "—— 全剧终 ——"}
  ]},
  "E08-S07": {"id": "E08-S07", "chapter": "E08", "title": "结局二　留下灯", "next": null, "time": "7月27日 下午", "place": "三巷旧柜档", "cue": "开齿声转拉开小台灯；窗外摊位照常换班", "beats": [
    {"id": "E08-S07.fewer.1", "sourceLine": 1750, "pickup": "fewer.1", "type": "line", "speaker": "旁白", "text": "小茵同意的更正已经送回当初看过的人。看的人不多，有人回了一个“原来是这样”，也有人没回。林雨把名单存进柜档，不再追着谁改口。"},
    {"id": "E08-S07.b01", "sourceLine": 1752, "type": "line", "speaker": "旁白", "text": "罗叔把配好齿的钥匙递给她。林雨开了柜门，试一下，又锁上。八月第一个周二，她搬到后排小间。靠窗那张桌子有个松动的插头，摆正了，台灯才亮。", "pages": ["罗叔把配好齿的钥匙递给她。林雨开了柜门，试一下，又锁上。", "八月第一个周二，她搬到后排小间。靠窗那张桌子有个松动的插头，摆正了，台灯才亮。"]},
    {"id": "E08-S07.cut-key", "type": "set", "text": "旧柜档配好的钥匙", "record": "cabinet-key", "scope": "private", "holder": "林雨", "detail": "每周二本人到场值班，只接收获准查阅的副本。", "origin": "permission"},
    {"id": "E08-S07.b02", "sourceLine": 1754, "type": "line", "speaker": "旁白", "text": "第一天下午没人来。阿岑从另一条街绕回来，说给她拍张开张照，刚按快门，林雨打了个哈欠。她接过相机看了一眼：「留着吧。今天就这样。」"},
    {"id": "E08-S07.light-routine", "sourceLine": 1756, "pickup": "light-routine", "type": "line", "speaker": "旁白", "text": "第二个周二两点，林雨先把写着“无人来”的上周记录夹回本子，替罗叔把新来的取件条按号平码好。粉叔隔墙喊她借火，她关了台灯去递，回来才看见女骑手抱着头盔站在门口。"},
    {"id": "E08-S07.b03", "sourceLine": 1758, "type": "line", "speaker": "旁白", "text": "女骑手来找四月留下的送达单。她盯着上面的「已到」，拿指头在地图上比了一下：「我哥平常等人的地方，还要往里骑三百米。」"},
    {"id": "E08-S07.b04", "sourceLine": 1760, "type": "line", "speaker": "林雨", "text": "你画。哪儿让人走错，就在哪儿圈。笔涩，摁两下。"},
    {"id": "E08-S07.b05", "sourceLine": 1762, "type": "line", "speaker": "女骑手", "text": "我想先打个电话。"},
    {"id": "E08-S07.b06", "sourceLine": 1764, "type": "line", "speaker": "旁白", "text": "林雨让开座位，去隔壁看粉叔收小炉火。回来时，那姑娘还在打电话。纸上刚添了一个小小的圈。林雨把台灯朝她那边挪了一点。"},
    {"id": "E08-S07.b07", "sourceLine": 1766, "type": "line", "speaker": "片尾", "text": "留下灯。八月第二个周二，桌底多一张取件牌：“来之前可以先问”。"},
    {"id": "E08-S07.b08", "sourceLine": 1768, "type": "end", "text": "—— 全剧终 ——"}
  ]},
  "E08-S08": {"id": "E08-S08", "chapter": "E08", "title": "结局三　签约", "next": null, "time": "7月18日 签字当晚", "place": "粉摊直播桌", "cue": "合同打款短信；电视回放只有林雨可见", "beats": [
    {"id": "E08-S08.onair.1", "sourceLine": 1775, "pickup": "onair.1", "type": "line", "speaker": "旁白", "text": "签字当晚，首页预告一过，小茵把机位压低，只照桌面。她对观众说，是自己穿过雨棚开的门；她亲手放出门轴声，在母亲开口前停住。"},
    {"id": "E08-S08.onair.2", "sourceLine": 1777, "pickup": "onair.2", "type": "line", "speaker": "旁白", "text": "第二天，有人到便利店把三月那句评论收回去，向阿琴说对不起。预告仍能单独转发，没进直播的人只看见门落下来。"},
    {"id": "E08-S08.b01", "sourceLine": 1779, "type": "line", "speaker": "旁白", "text": "第一笔保底到账，团队结清器材租金。阿岑买下用惯的镜头，先去替朋友婚礼补一组家人合照。林雨搬进有独立灶台的房，蒸第一碟肠粉时把粉浆倒厚了，一折就断。", "pages": ["第一笔保底到账，团队结清器材租金。阿岑买下用惯的镜头，先去替朋友婚礼补一组家人合照。", "林雨搬进有独立灶台的房，蒸第一碟肠粉时把粉浆倒厚了，一折就断。"]},
    {"id": "E08-S08.b02", "sourceLine": 1781, "type": "line", "speaker": "旁白", "text": "审定片还在涨。有人从空巷认出阿琴的店，拿手机等关闸；阿琴叫儿子挡过两回，把侧门的灯往里挪一尺。小茵的私信没有骂，只问：那七秒以后呢？", "pages": ["审定片还在涨。有人从空巷认出阿琴的店，拿手机等关闸；阿琴叫儿子挡过两回，把侧门的灯往里挪一尺。", "小茵的私信没有骂，只问：那七秒以后呢？"]},
    {"id": "E08-S08.b03", "sourceLine": 1783, "type": "line", "speaker": "旁白", "text": "林雨在自己的号里打好更正，又回去看首页切片。合同摊在手边，她打给阿琴，听到最后一声，电话断了。"},
    {"id": "E08-S08.b04", "sourceLine": 1785, "type": "line", "speaker": "旁白", "text": "微波炉响。新屋没有电视，炉门黑玻璃里却坐着一个剪片的人，一遍遍倒回她自己切掉门轴声的那一格。那人每剪走一句话，左手都先摸耳垂，已经揉红。"},
    {"id": "E08-S08.b05", "sourceLine": 1787, "type": "line", "speaker": "阿岑的语音", "text": "下周那条你自己定。要我抬机子就喊；要我说门没开，那句别写我。"},
    {"id": "E08-S08.b06", "sourceLine": 1789, "type": "line", "speaker": "旁白", "text": "林雨吃掉凉了的肠粉。玻璃里的人终于抬头，叫了她全名。"},
    {"id": "E08-S08.b07", "sourceLine": 1791, "type": "line", "speaker": "片尾", "text": "签约。八月，《今宵剧场》下一位，林雨。"},
    {"id": "E08-S08.b08", "sourceLine": 1793, "type": "end", "text": "—— 全剧终 ——"}
  ]}
}};
